function icon(n,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.grid}</svg>`}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function attr(v){return esc(v)}
function norm(v){return String(v).toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim()}
function best(r){return RANK[r.c39]>=RANK[r.ftt]?r.c39:r.ftt}
function statusOf(r,scope=STATE.scope){return scope==='best'?best(r):r[scope]}
function confidenceOf(r,scope=STATE.scope){if(scope!=='best')return r[scope+'Confidence'];let selected=RANK[r.c39]>=RANK[r.ftt]?'c39':'ftt';return r[selected+'Confidence']}
function counts(rows=DATA.rows,scope=STATE.scope){const o={D:0,P:0,I:0,N:0};for(const r of rows)o[statusOf(r,scope)]++;return o}
function badge(s,short=false){return `<span class="badge ${s}"><i class="status-dot" aria-hidden="true"></i>${short?SHORT[s]:LABELS[s]}</span>`}
function scopeName(){return STATE.scope==='best'?'Сильнейшее основание':STATE.scope==='c39'?'ФТ сервиса 39':'ФТТ 57.1'}
function matchesText(r,q){
 if(!q)return true; const numberMatch=q.match(/^(?:ф[тt]|ft)?[\s-]*0*(\d+)$/i);
 if(numberMatch){const n=Number(numberMatch[1]);return STATE.numbering==='current'?Number(r.number.replace(/\D/g,''))===n:r.id.startsWith('ФТ-')&&Number(r.id.replace(/\D/g,''))===n;}
 const hay=norm([r.id,r.number,r.text,r.sectionTitle,r.c39Gap,r.fttGap,...r.concepts.map(k=>CONCEPTS.get(k).title)].join(' '));return norm(q).split(' ').every(t=>hay.includes(t));
}
function filteredRows(){return DATA.rows.filter(r=>matchesReview(r)&&matchesText(r,STATE.query)&&(STATE.status==='all'||statusOf(r)===STATE.status)&&(STATE.section==='all'||r.section===STATE.section)&&(STATE.confidence==='all'||confidenceOf(r)===STATE.confidence)&&(STATE.revision==='all'||(STATE.revision==='changed'?r.revision==='Текст изменен':STATE.revision==='new'?r.revision==='Новый пункт ВСТЕ':r.revision!=='Без изменения текста'))&&(!STATE.concept||r.concepts.includes(STATE.concept)))}
function filteredConcepts(){return DATA.concepts.filter(c=>(STATE.group==='all'||c.group===STATE.group)&&(STATE.status==='all'||statusOf(c)===STATE.status)&&(!STATE.query||norm(STATE.query).split(' ').every(t=>norm([c.id,c.title,c.conclusion,c.action].join(' ')).includes(t))||c.requirements.some(id=>matchesText(REQS.get(id),STATE.query))))}
function evidenceFor(refs){
 const ids=new Set();
 for(const m of refs.matchAll(/(C39|FTT|CMP)-P(\d+)(?:[–—-](?:(?:C39|FTT|CMP)-)?P?(\d+))?/g)){
  const start=Number(m[2]),end=m[3]?Number(m[3]):start;
  if(end<start||end-start>10000)continue;
  for(let n=start;n<=end;n++){const id=`${m[1]}-P${String(n).padStart(5,'0')}`;if(EVIDENCE.has(id))ids.add(id)}
 }
 for(const m of refs.matchAll(/(?:C39|FTT|CMP)-(?:FIG-[A-Z]\d+|C\d+)/g)){if(EVIDENCE.has(m[0]))ids.add(m[0])}
 for(const m of refs.matchAll(/APP147-(?:FIG-P\d+|P\d+)|AUTHOR-20261014/g))if(EVIDENCE.has(m[0]))ids.add(m[0]);
 return [...ids].map(id=>EVIDENCE.get(id));
}
function evidenceHtml(refs){const rows=evidenceFor(refs);if(!rows.length)return `<p class="subtle">${refs&&!refs.includes('не найдено')?'Связанные пункты указаны в ссылке выше.':'Подтверждающее основание в рассмотренном документе не найдено. Это вывод в границах проверенной редакции.'}</p>`;return `<details class="quote-disclosure"><summary>Открыть основания · ${rows.length}</summary><div class="quote-list">${rows.map(e=>`<article class="evidence-quote"><div class="evidence-meta"><b>${esc(e[0])}</b><span>${esc(e[2])}</span>${e[3]!=='Без отдельного номера'?`<span>${esc(e[3])}</span>`:''}</div><blockquote>${esc(e[4])}</blockquote>${e[5]?`<span class="context-note">${esc(e[5])}</span>`:''}</article>`).join('')}</div></details>`}
function sourceCard(title,status,confidence,refs,gap='',review=null){return `<section class="source-card"><div class="source-card-head"><div><h4>${title}</h4><small>${confidence?'Достоверность оценки: '+esc(confidence):'Текущая редакция'}</small></div>${badge(status)}</div><div class="source-card-body">${gap?`<p>${esc(gap)}</p>`:''}${refs?`<div class="refs-text">${esc(refs)}</div>`:''}${evidenceHtml(refs)}</div>${review?reviewEditor(review.kind,review.id,review.source):''}</section>`}
function selectedAttr(a,b){return a===b?' selected':''}
function legendFilters(){return `<div class="legend-filters"><button class="legend-filter ${STATE.status==='all'?'active':''}" data-action="status" data-value="all" aria-pressed="${STATE.status==='all'}">Все оценки</button>${CODES.map(s=>`<button class="legend-filter ${s} ${STATE.status===s?'active':''}" data-action="status" data-value="${s}" aria-pressed="${STATE.status===s}"><i class="status-dot"></i>${LABELS[s]}</button>`).join('')}</div>`}
function renderNav(){document.getElementById('nav').innerHTML=NAV.map(([id,title,ic,n])=>`<button class="nav-item ${STATE.view===id?'active':''}" data-action="view" data-value="${id}" ${STATE.view===id?'aria-current="page"':''} title="${title}">${icon(ic)}<span>${title}</span><small>${n}</small></button>`).join('');document.getElementById('crumb').textContent=NAV.find(n=>n[0]===STATE.view)[1]}
function renderMetrics(){const c=counts();const captions={D:'Прямая формулировка в источнике',P:'Функция есть, часть условий отсутствует',I:'Нужна расширительная трактовка',N:'Основание не обнаружено'};document.getElementById('metrics').innerHTML=CODES.map(s=>`<button class="metric ${s} ${STATE.status===s?'selected':''}" data-action="metric" data-value="${s}" aria-label="Показать ${c[s]} требований с оценкой ${LABELS[s]}"><div class="metric-top"><span class="metric-title"><i class="status-dot"></i>${LABELS[s]}</span><span aria-hidden="true">↗</span></div><div class="metric-main"><strong>${c[s]}</strong><small>${(c[s]/417*100).toLocaleString('ru-RU',{maximumFractionDigits:1})}%</small></div><span class="metric-foot">${captions[s]}</span></button>`).join('');document.getElementById('scope-caption').textContent=STATE.scope==='best'?'Из 417 требований. Для каждого выбрана более сильная из двух оценок; основания не складываются автоматически.':'Из 417 требований. Оценка по '+scopeName()+'; показатели рассчитаны по всему документу, до фильтров.'}
function renderMap(){const visible=new Set(filteredRows().map(r=>r.id));const cs=filteredConcepts();return `<div class="topology"><section class="topology-main"><div class="section-title"><div><h2>Топография требований</h2><p>Один квадрат — одно требование. Нажмите, чтобы открыть основание.</p></div><small>417 ФТ</small></div><div class="heatmap" aria-label="Карта всех 417 требований">${DATA.rows.map(r=>`<button class="tile ${statusOf(r)} review-${reviewState('requirement',r.id)} ${visible.has(r.id)?'':'faded'}" data-action="requirement" data-value="${r.id}" title="${attr(r.number+' · база '+r.id+' · '+LABELS[statusOf(r)]+'\n'+r.text)}" aria-label="${attr(r.number+': '+LABELS[statusOf(r)]+'; '+r.text)}"></button>`).join('')}</div><div class="map-help"><span>Порядок — по текущей редакции. Пустой ФТ-92 исключен.</span><button class="text-button" data-action="view" data-value="requirements">К списку ${visible.size} ФТ →</button></div></section><aside class="insight"><p class="eyebrow">ВАЖНОЕ РАЗЛИЧИЕ</p><h3>Закрытый и защищенный —<br>разные контуры.</h3><p>Второй (закрытый) контур не подтверждает защищенный контур ПДн на ГосТех. Приложение 147 рассматривается как отдельный источник.</p><button data-action="appendix">Приложение 147 и исправление ↗</button></aside></div><div class="atlas-header"><h2>Карта концепций</h2><small>50 тем · 3 документа</small></div><div class="groups">${DATA.groups.map(g=>{const gc=DATA.concepts.filter(c=>c.group===g.id);return `<button class="group ${STATE.group===g.id?'active':''}" data-action="group" data-value="${g.id}" aria-pressed="${STATE.group===g.id}">${icon(g.icon)}<span>${esc(g.title)}<small>${gc.length} концепций</small></span><b>↗</b></button>`}).join('')}</div><div class="section-title"><div><h3>${STATE.group==='all'?'Все концепции':esc(DATA.groups.find(g=>g.id===STATE.group).title)}</h3><p>Связь показывает сопоставление текстов, а не потоки данных системы.</p></div><button class="text-button" data-action="group" data-value="all">Показать все 50</button></div>${legendFilters()}${cs.length?`<div class="concept-list"><div class="concept-list-head"><span>КОНЦЕПЦИЯ · нажмите для раскрытия</span><div class="source-head"><span><strong>ФТ сервиса 39</strong>17.01.2025</span><span><strong>ФТ ЦМПОН</strong>2.0.2 · ВСТЕ</span><span><strong>ФТТ ГИС ЦАП</strong>57.1</span></div></div>${cs.map(c=>`<button class="concept-node" data-action="concept" data-value="${c.id}" aria-label="${attr(c.title)}. Сервис 39: ${LABELS[c.c39]}. ЦМПОН: ${LABELS[c.cmp]}. ФТТ: ${LABELS[c.ftt]}"><span class="concept-label"><small>${c.id}</small><strong>${esc(c.title)}${reviewChip('concept',c.id)}</strong></span><span class="mini-network"><span class="network-node ${c.c39}"><i class="status-dot"></i>${SHORT[c.c39]}</span><span class="network-node center ${c.cmp}"><i class="status-dot"></i>${SHORT[c.cmp]}</span><span class="network-node ${c.ftt}"><i class="status-dot"></i>${SHORT[c.ftt]}</span></span></button>`).join('')}</div>`:empty('Подходящих концепций нет','Попробуйте другую тему, оценку или поисковый запрос.')}<p class="atlas-note">Концепции могут пересекаться и не суммируются с требованиями. Наличие общей концепции не означает покрытия всех ее деталей.</p>`}
function empty(title,msg){return `<div class="empty"><h3>${title}</h3><p>${msg}</p><button class="button" data-action="clear">Сбросить фильтры</button></div>`}
function renderRequirements(){const rows=filteredRows(),pages=Math.max(1,Math.ceil(rows.length/40));STATE.page=Math.min(STATE.page,pages);const slice=rows.slice((STATE.page-1)*40,STATE.page*40);return `<div class="section-title"><div><h2>Все требования</h2><p>Точный текст, степень покрытия и достоверность вывода по каждому источнику.</p></div><small>${rows.length} / 417</small></div><div class="filters"><label>Раздел<select id="section"><option value="all">Все разделы</option>${Object.entries(DATA.sections).map(([k,v])=>`<option value="${k}"${selectedAttr(k,STATE.section)}>${esc(v)}</option>`).join('')}</select></label><label>Достоверность<select id="confidence"><option value="all">Любая</option>${['Высокая','Средняя','Низкая'].map(v=>`<option${selectedAttr(v,STATE.confidence)}>${v}</option>`).join('')}</select></label><label>Редакция<select id="revision"><option value="all">Все пункты</option><option value="any"${selectedAttr('any',STATE.revision)}>Есть изменения</option><option value="changed"${selectedAttr('changed',STATE.revision)}>Изменен текст</option><option value="new"${selectedAttr('new',STATE.revision)}>Новые ВСТЕ</option></select></label><label>Номер ФТ<select id="numbering"><option value="current"${selectedAttr('current',STATE.numbering)}>Текущий</option><option value="base"${selectedAttr('base',STATE.numbering)}>Базовый</option></select></label>${reviewFilter()}${STATE.concept?`<span class="filter-tag">${esc(CONCEPTS.get(STATE.concept).title)}<button data-action="clear-concept" aria-label="Убрать фильтр концепции">×</button></span>`:''}</div>${legendFilters()}${rows.length?`<div class="table-wrap"><table class="req-table"><thead><tr><th>${STATE.numbering==='current'?'Текущий №':'ID базы'}</th><th>Требование ЦМПОН</th><th>ФТ сервиса 39</th><th>ФТТ 57.1</th><th>Сильнейшее</th></tr></thead><tbody>${slice.map(r=>`<tr><td><button class="req-id" data-action="requirement" data-value="${r.id}">${esc(STATE.numbering==='current'?r.number:r.id)}${r.revision!=='Без изменения текста'?'<i class="change-dot" title="Есть изменение редакции"></i>':''}<span class="id-sub">${STATE.numbering==='current'?'база '+esc(r.id):'сейчас '+esc(r.number)}</span></button></td><td><button class="req-text" data-action="requirement" data-value="${r.id}">${esc(r.text)}</button><span class="section-ref">${esc(r.sectionTitle)}</span></td><td>${badge(r.c39,true)}<span class="conf">${r.c39Confidence}</span>${reviewChip('requirement',r.id,'c39')}</td><td>${badge(r.ftt,true)}<span class="conf">${r.fttConfidence}</span>${reviewChip('requirement',r.id,'ftt')}</td><td>${badge(best(r),true)}</td></tr>`).join('')}</tbody></table></div><div class="page-controls"><span>${(STATE.page-1)*40+1}–${Math.min(STATE.page*40,rows.length)} из ${rows.length}</span><div><button class="button" data-action="page" data-value="-1" ${STATE.page===1?'disabled':''}>← Назад</button><span>${STATE.page} / ${pages}</span><button class="button" data-action="page" data-value="1" ${STATE.page===pages?'disabled':''}>Далее →</button></div></div>`:empty('Требования не найдены','Проверьте фильтры и режим поиска по номеру: текущая или базовая нумерация.')}<p class="atlas-note">Цифровой запрос ищет точный номер в выбранной нумерации. «Сильнейшее» — максимум двух отдельных оценок, без объединения условий из разных источников.</p>`}
function renderChanges(){const query=norm(STATE.query);const versions=DATA.versions.filter(v=>!query||norm(v.join(' ')).includes(query));return `<div class="section-title"><div><h2>Что изменилось в редакции</h2><p>База 2.0.2 → версия 2.0.2 от 14.10.2026 с дополнениями ВСТЕ.</p></div><small>24 ПУНКТА</small></div><div class="change-intro"><div class="change-stat"><strong>17</strong><span>требований с измененным текстом</span></div><div class="change-stat"><strong>7</strong><span>новых требований ВСТЕ</span></div><div class="numbering-note"><h3>Два номера, один пункт</h3><p>Базовые ФТ-85…410 теперь имеют номера ФТ-93…418. Новые ФТ-85…91 помечены ВСТЕ-01…07. Пустой ФТ-92 не включен в анализ.</p></div></div><p class="subtle" style="margin:0 0 16px">Этот раздел показывает сравнение редакций; фильтры покрытия к нему не применяются. Поиск работает по текстам обеих версий.</p>${versions.length?versions.map(v=>`<details class="change-row"><summary><strong>${esc(v[1])}</strong><small>${esc(v[0])}</small><span class="revision-label">${esc(v[2])}</span></summary><div class="diff"><div><h4>БАЗОВАЯ РЕДАКЦИЯ 2.0.2</h4><p>${esc(v[3])}</p></div><div><h4>ТЕКУЩАЯ РЕДАКЦИЯ · ВСТЕ</h4><p>${esc(v[4])}</p></div></div><button class="button" data-action="requirement" data-value="${v[0]}">Проверить основания ↗</button></details>`).join(''):empty('Изменений по запросу нет','Попробуйте другое слово или очистите поиск.')}`}
function renderMethods(){const c39=counts(DATA.rows,'c39'),ftt=counts(DATA.rows,'ftt'),union=counts(DATA.rows,'best');return `<div class="section-title"><div><h2>Как читать атлас</h2><p>Границы сравнения, шкалы оценки и идентификация источников.</p></div><small>МЕТОДИКА</small></div><div class="notice"><b>Это аналитическое сопоставление текстов.</b> Оно не подтверждает фактическое выполнение работ, приемку, согласование требований или их включение в договорной объем. Права и использование ЕРН определяются отдельным санкционированным порядком.</div><div class="method-grid"><section class="method-card"><h3>01 / Степень покрытия</h3>${[['D','Норма или функция выражена прямо, без существенной подмены смысла.'],['P','Функция предусмотрена, но отдельные условия текущего требования отсутствуют.'],['I','Найдена только общая, соседняя или расширительно трактуемая норма.'],['N','Подтверждающее основание в проверенных редакциях не обнаружено.']].map(([s,t])=>`<div class="definition"><div>${badge(s)}</div><p>${t}</p></div>`).join('')}</section><section class="method-card"><h3>02 / Достоверность оценки</h3><p><b>Высокая</b> — прямая и достаточно однозначная привязка. <b>Средняя</b> — совпадение по функции с неполным набором условий. <b>Низкая</b> — косвенная смысловая связь.</p><p style="margin-top:13px">Это порядковая экспертная шкала, а не рассчитанная вероятность. Для «не найдено» оценка ограничена просмотренными версиями. Достоверность «сильнейшего основания» берется из выбранного источника; при равных оценках — из С39.</p><p style="margin-top:13px">Общая концепция может присутствовать прямо, хотя конкретные требования внутри нее покрыты лишь частично.</p></section><section class="method-card wide"><h3>03 / Контрольные итоги</h3><div class="table-wrap"><table class="compact-table"><thead><tr><th>Источник</th>${CODES.map(s=>`<th>${LABELS[s]}</th>`).join('')}<th>Всего</th></tr></thead><tbody>${[['Сервис 39',c39],['ФТТ 57.1',ftt],['Сильнейшее из двух',union]].map(([t,c])=>`<tr><td>${t}</td>${CODES.map(s=>`<td>${c[s]}</td>`).join('')}<td>417</td></tr>`).join('')}</tbody></table></div><p style="margin-top:12px">В базе 410 требований; в текущей редакции учтено 417 непустых требований, включая 7 новых ВСТЕ. 50 концепций — отдельный тематический срез. В доказательной базе ${DATA.evidence.length} записей, включая комментарии и описания схем.</p></section><section class="method-card"><h3>04 / Ссылки и нумерация</h3><ul><li>Текущий номер взят из редакции от 14.10.2026. Базовый ID сохраняет связь с ранее разосланной 2.0.2.</li><li>Коды вида C39-P00223 — аналитические локаторы абзацев. Они не являются исходными номерами ФТ. Для деловой ссылки используйте документ, раздел и цитату.</li><li>ВСТЕ-01…07 — аналитические ID новых пунктов, а не новые версии документа.</li><li>Цитаты показывают контекст и специальные ограничения. Текст комментария Word не считается утвержденным требованием.</li></ul></section><section class="method-card"><h3>05 / Что важно не смешивать</h3><ul><li>«Не найдено» относится к проверенным С39 и ФТТ 57.1, а не ко всем возможным материалам проекта.</li><li>Второй (закрытый) контур и защищенный контур ПДн — разные контуры. Приложение 147 не является частью С39/ФТТ.</li><li>Открытый контур не означает общедоступность данных.</li><li>Общие функции ЦМПОН для ЛПХ не равны полному отраслевому циклу ЛПХ.</li><li>Тест-кейсы и допуски требуют утверждения владельцами методик и ИБ до проведения испытаний.</li><li>«Сильнейшее из двух» не объединяет отдельные условия двух источников в одно доказательство.</li></ul></section><section class="method-card wide"><h3>06 / Проверенные редакции источников</h3>${DATA.sources.map(s=>`<div class="source-file"><span>${esc(s.code)}</span><div><p>${esc(s.filename)}</p><small>${s.paragraphs} абзацев в извлечении</small><details><summary>Контрольная сумма SHA-256</summary><code>${esc(s.sha256)}</code></details></div></div>`).join('')}<p>В атлас встроены тексты и аналитические выводы. Файлы источников не изменены. Для официального цитирования сверяйте раздел в указанной исходной редакции.</p></section><section class="method-card wide"><h3>Приложение 147: отдельный источник</h3><p>${esc(DATA.supplement.role)}</p><p>${esc(DATA.analyticalRevision.boundary)}</p><button class="button" data-action="appendix" style="margin-top:12px">Открыть выдержки и схему ↗</button></section><section class="method-card wide"><h3>07 / Работа с файлом</h3><p>Поиск и все карточки работают без сети. Нажмите <b>/</b>, чтобы перейти к поиску, и <b>Esc</b>, чтобы закрыть карточку. Номер ищется точно: например, «ФТ-93». В разделе требований можно переключить поиск на базовую нумерацию. Экспорт CSV сохраняет отфильтрованные требования, оценки, обоснования и ссылки; файл открывается в Excel. Копирование вывода не меняет исходные документы. Раздел «Рецензирование» позволяет оспорить или подтвердить оценку отдельно по С39 и ФТТ, указать автора и обоснование. Мнения сохраняются в этом браузере; JSON переносит все рецензии и их историю между рабочими копиями, CSV — активный реестр по фильтрам. В «Географии требований» страны обозначают темы, города — концепции, точки — ФТ. Линии внутри страны связывают выбранную концепцию с требованиями, между странами — темы с общими ФТ. Это не схема архитектуры или потоков данных.</p></section></div>`}
function render(){detachCosmos();detachArcade();document.body.classList.toggle('is-cosmos',STATE.view==='cosmos');document.body.classList.toggle('is-arcade',STATE.view==='arcade');renderNav();syncMobileNavigation();renderMetrics();document.getElementById('content').innerHTML=STATE.view==='map'?renderMap():STATE.view==='requirements'?renderRequirements():STATE.view==='changes'?renderChanges():STATE.view==='reviews'?renderReviews():STATE.view==='cosmos'?renderCosmos():STATE.view==='arcade'?renderArcade():renderMethods();document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon)});document.getElementById('search').value=STATE.query;document.getElementById('scope').value=STATE.scope;if(STATE.view==='cosmos')mountCosmos();if(STATE.view==='arcade')mountArcade()}
function setView(view,scroll=false){if(!NAV.some(n=>n[0]===view))return;setMobileMenu(false,false);STATE.view=view;STATE.page=1;if(view==='cosmos'){STATE.numbering='current';STATE.reviewStatus='all'}if(['map','cosmos'].includes(view))Object.assign(STATE,{section:'all',confidence:'all',revision:'all',concept:null});render();if(scroll)document.getElementById('content').scrollIntoView({behavior:'auto',block:'start'})}
function openDetail(kind,id){
 if(kind==='appendix'){STATE.selected={kind,id:'APP147'};document.getElementById('drawer-type').textContent='ПРИЛОЖЕНИЕ 147 / УТОЧНЕНИЕ';document.getElementById('detail-body').innerHTML=appendixDetail();const dlg=document.getElementById('detail');if(!dlg.open)dlg.showModal();dlg.scrollTop=0;dlg.querySelector('[data-action="close"]').focus();return;}
 const isConcept=kind==='concept',item=isConcept?CONCEPTS.get(id):REQS.get(id);if(!item)return;
 STATE.selected={kind,id};const d=document.getElementById('detail');document.getElementById('drawer-type').textContent=isConcept?'КОНЦЕПЦИЯ / '+id:'ТРЕБОВАНИЕ / '+item.number;
 document.getElementById('detail-body').innerHTML=isConcept?conceptDetail(item):requirementDetail(item);
 if(!d.open)d.showModal();d.scrollTop=0;const close=d.querySelector('[data-action="close"]');if(close)close.focus();
}
function requirementDetail(r){const v=VERSIONS.get(r.id);return `<div class="drawer-kicker"><span>${esc(r.number)} · текущая нумерация</span><span>База: ${esc(r.id)}</span>${r.revision!=='Без изменения текста'?`<span class="revision-label">${esc(r.revision)}</span>`:''}</div><h2 class="drawer-title" id="detail-title">Требование ${esc(r.number)}</h2><p class="detail-cmp"><strong>${esc(r.sectionTitle)}</strong><br>ФТ ЦМПОН 2.0.2 · 14.10.2026 · ${esc(r.paragraph)}</p><blockquote class="requirement-quote">${esc(r.text)}</blockquote><div class="drawer-summary"><span>В текущих ФТ: <strong>есть</strong></span><span>Сильнейшее основание:</span>${badge(best(r))}</div>${r.note?`<div class="notice">${esc(r.note)}</div>`:''}<div class="drawer-section"><h3>Проверка по исходным документам</h3>${sourceCard('ФТ сервиса 39',r.c39,r.c39Confidence,r.c39Refs,r.c39Gap,{kind:'requirement',id:r.id,source:'c39'})}${sourceCard('ФТТ ГИС ЦАП 57.1',r.ftt,r.fttConfidence,r.fttRefs,r.fttGap,{kind:'requirement',id:r.id,source:'ftt'})}</div>${supplementCard(DATA.supplement.requirementEvidence[r.id])}${r.concepts.length?`<div class="drawer-section"><h3>Связанные концепции</h3><div class="related">${r.concepts.map(k=>`<button class="concept-pill" data-action="concept" data-value="${k}">${k} · ${esc(CONCEPTS.get(k).title)} ↗</button>`).join('')}</div></div>`:''}${v?`<div class="drawer-section"><h3>Сравнение редакций</h3><div class="diff"><div><h4>БАЗОВАЯ 2.0.2</h4><p>${esc(v[3])}</p></div><div><h4>ТЕКУЩАЯ · ВСТЕ</h4><p>${esc(v[4])}</p></div></div></div>`:''}<p class="subtle" style="margin-top:25px">Оценка касается формулировок документов. Реализация, приемка и договорной объем этим сопоставлением не подтверждаются.</p>`}
function conceptDetail(c){return `<div class="drawer-kicker"><span>${c.id} · ${esc(DATA.groups.find(g=>g.id===c.group).title)}</span><span>${c.requirements.length} связанных ФТ</span></div><h2 class="drawer-title" id="detail-title">${esc(c.title)}</h2><div class="detail-network"><div><small>ФТ СЕРВИСА 39</small>${badge(c.c39)}<span class="conf">Достоверность: ${c.c39Confidence.toLowerCase()}</span></div><div><small>ФТ ЦМПОН · 2.0.2</small>${badge(c.cmp)}<span class="conf">Текущая редакция</span></div><div><small>ФТТ · 57.1</small>${badge(c.ftt)}<span class="conf">Достоверность: ${c.fttConfidence.toLowerCase()}</span></div></div><section class="conclusion-box"><small>ВЫВОД ДЛЯ ОБОСНОВАНИЯ</small><p>${esc(c.conclusion)}</p></section><div class="action-box"><b>Как отработать</b>${esc(c.action)}</div><div class="drawer-section"><h3>Доказательная база</h3>${sourceCard('ФТ сервиса 39',c.c39,c.c39Confidence,c.c39Refs,'',{kind:'concept',id:c.id,source:'c39'})}${sourceCard('ФТТ ГИС ЦАП 57.1',c.ftt,c.fttConfidence,c.fttRefs,'',{kind:'concept',id:c.id,source:'ftt'})}${sourceCard('Текущие ФТ ЦМПОН',c.cmp,'',c.cmpRefs)}</div>${supplementCard(DATA.supplement.conceptEvidence[c.id])}<div class="drawer-section"><h3>Связанные требования · ${c.requirements.length}</h3>${c.requirements.length?`<p class="subtle">Кнопки показывают текущие номера. Базовый ID указан в подсказке и карточке.</p><div class="related">${c.requirements.map(id=>{const r=REQS.get(id);return `<button data-action="requirement" data-value="${r.id}" title="${attr(r.id+' · '+r.text)}">${r.number}</button>`}).join('')}</div><button class="button primary" data-action="concept-filter" data-value="${c.id}" style="margin-top:15px">Показать в таблице →</button>`:'<p class="subtle">Отдельный набор нумерованных требований полного отраслевого цикла не выделен. См. вывод и ссылки выше.</p>'}</div><p class="subtle" style="margin-top:25px">Наличие общей концепции в источнике не означает, что все специальные условия текущих требований уже предусмотрены.</p>`}
function copyText(){if(!STATE.selected)return '';const {kind,id}=STATE.selected;if(kind==='appendix')return 'Исправление от 14.10.2026. Второй (закрытый) контур и защищенный контур ПДн — разные контуры. Защищенный контур ПДн на ГосТех описан в Приложении 147 (стр. 2–5). Это отдельный проектный источник, а не часть С39/ФТТ. В ФТТ §§ 1.6/1.6.1 отдельно упоминается загрузка ЕРН в контур обработки ПДн для РСН; это частичное основание. '+DATA.analyticalRevision.boundary;if(kind==='concept'){const c=CONCEPTS.get(id);return `${c.id}. ${c.title}\n\nФТ ЦМПОН: ${LABELS[c.cmp]}.\nФТ сервиса 39: ${LABELS[c.c39]}; достоверность: ${c.c39Confidence}.\n${c.c39Refs||'Подтверждающее основание не найдено.'}\nФТТ 57.1: ${LABELS[c.ftt]}; достоверность: ${c.fttConfidence}.\n${c.fttRefs||'Подтверждающее основание не найдено.'}\n\nВывод: ${c.conclusion}\nПредлагаемая отработка: ${c.action}\n\nСвязанные ФТ (текущий номер / базовый ID): ${c.requirements.map(k=>REQS.get(k).number+' / '+k).join('; ')}\n\nАнализ текстов по состоянию на 14.10.2026; реализация и договорной объем не проверялись.`}const r=REQS.get(id);return `${r.number} (базовый ID ${r.id}). ${r.text}\n\nТекущие ФТ ЦМПОН: ${r.sectionTitle}, ${r.paragraph}.\nФТ сервиса 39: ${LABELS[r.c39]}; достоверность: ${r.c39Confidence}.\n${r.c39Gap}\n${r.c39Refs}\n\nФТТ 57.1: ${LABELS[r.ftt]}; достоверность: ${r.fttConfidence}.\n${r.fttGap}\n${r.fttRefs}\n\nАнализ текстов по состоянию на 14.10.2026; реализация и договорной объем не проверялись.`}
function supplementCard(ids){if(!ids?.length)return '';return `<section class="source-card supplement"><div class="source-card-head"><div><h4>Отдельный источник · Приложение 147</h4><small>Проект. Не засчитывается как наличие в С39/ФТТ</small></div><button class="text-button" data-action="appendix">Открыть ↗</button></div><div class="source-card-body">${evidenceHtml(ids.join(' '))}</div></section>`}
function appendixDetail(){return `<div class="drawer-kicker"><span>Уточнение анализа · 14.10.2026</span></div><h2 class="drawer-title" id="detail-title">Закрытый и защищенный контуры</h2><div class="contour-types"><section><h3>Закрытый / второй</h3><p>Отдельный контур для сведений государственной тайны — в терминологии уточнения автора. Упоминания в С39 и ФТТ не подтверждают защищенный контур ПДн.</p></section><section><h3>Защищенный / ПДн</h3><p>Контур ГИС ЦАП на ГосТех для персональных данных, включая специальные категории. Обработка ЕРН описана в Приложении 147, стр. 2–5.</p></section></div><div class="notice">${esc(DATA.analyticalRevision.boundary)}</div><section class="conclusion-box"><small>КАК ИСПРАВЛЕН ВЫВОД</small><p>Ссылки на второй контур исключены из подтверждения защищенной обработки ПДн. В ФТТ сохраняется самостоятельное частичное основание — целевой результат загрузки ЕРН в контур обработки ПДн для РСН (§§ 1.6, 1.6.1). Приложение 147 трассируется отдельно.</p></section><div class="drawer-section"><h3>Точные выдержки из Приложения 147</h3><p class="subtle">Документ имеет статус проекта концептуальной схемы. Наличие положения в проекте не подтверждает его согласование или наличие в С39/ФТТ.</p>${evidenceHtml('APP147-P02 APP147-P03 APP147-P04 APP147-FIG-P05')}</div><div class="drawer-section"><h3>Границы исходных документов</h3>${evidenceHtml('C39-P00091 FTT-P00506 FTT-P00378 FTT-P00456')}</div><details class="quote-disclosure" style="margin-top:24px"><summary>Схема · Приложение 147, стр. 5</summary><p class="subtle" style="margin:10px 0">Для чтения мелких подписей прокручивайте изображение по горизонтали.</p><div class="scheme-scroll"><img class="appendix-scheme" src="${DATA.supplement.schemeDataUri}" alt="Исходная схема Приложения 147: защищенный контур, открытый контур, шлюз и специальные роли ЕРН"></div></details><div class="related" style="margin-top:24px">${['K01','K02','K06','K07'].map(k=>`<button data-action="concept" data-value="${k}">${k} · ${esc(CONCEPTS.get(k).title)} ↗</button>`).join('')}</div><p class="subtle" style="margin-top:20px">Источник: ${esc(DATA.supplement.filename)}, 5 страниц.<br>SHA-256: <span style="overflow-wrap:anywhere">${DATA.supplement.sha256}</span></p>`}
function csvCell(s){let t=String(s??'');if(/^[\s]*[=+@-]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'}
function csvContent(rows){const fields=['Текущий номер','Базовый ID / новый пункт','Требование','Есть в текущих ФТ','С39 — покрытие','С39 — достоверность','С39 — ссылки','С39 — обоснование','ФТТ — покрытие','ФТТ — достоверность','ФТТ — ссылки','ФТТ — обоснование','Сильнейшее основание','Раздел','Изменение редакции','Абзац ЦМПОН','Примечание'];return '\uFEFF'+[fields,...rows.map(r=>[r.number,r.id,r.text,'Есть',LABELS[r.c39],r.c39Confidence,r.c39Refs,r.c39Gap,LABELS[r.ftt],r.fttConfidence,r.fttRefs,r.fttGap,LABELS[best(r)],r.sectionTitle,r.revision,r.paragraph,r.note])].map(row=>row.map(csvCell).join(';')).join('\r\n')}
let toastTimer;
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000)}
async function copyConclusion(){const text=copyText()+selectedReviewText();try{if(!navigator.clipboard)throw new Error('clipboard unavailable');await navigator.clipboard.writeText(text);toast('Вывод и ссылки скопированы')}catch{let ta=document.getElementById('copy-fallback');if(!ta){ta=document.createElement('textarea');ta.id='copy-fallback';ta.className='copy-fallback';ta.setAttribute('aria-label','Текст вывода для копирования');document.getElementById('detail-body').prepend(ta)}ta.value=text;ta.focus();ta.select();toast('Текст выделен. Нажмите Ctrl+C или «Копировать».')}}
function exportCSV(){const rows=STATE.view==='cosmos'?spaceRows():filteredRows();if(!rows.length){toast('Нет требований для выгрузки');return}const blob=new Blob([csvContent(rows)],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ЦМПОН_основания_${rows.length}_ФТ_14.10.2026.csv`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast(`Выгружено требований: ${rows.length}`)}
function resetFilters(){Object.assign(STATE,{status:'all',query:'',section:'all',confidence:'all',revision:'all',concept:null,reviewStatus:'all',page:1});REVIEW.filter='all';REVIEW.source='all';REVIEW.kind='all';REVIEW.page=1;SPACE.review='all';SPACE.concept=null;SPACE.page=1;document.getElementById('search').value='';render()}
function closeDetail(){document.getElementById('detail').close()}
function initialize(){
 loadReviews();setupReviews();setupCosmos();setupArcade();setupMobile();setupTournament();render();
 document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const {action,value}=b.dataset;
  if(mobileAction(action,value)){event.preventDefault();return}
  if(action==='view'){event.preventDefault();if(isMobileLayout())mobileNavigate(value);else setView(value)}
  else if(action==='metric'){STATE.status=value;STATE.view='requirements';STATE.page=1;render();document.getElementById('content').scrollIntoView({block:'start'})}
  else if(action==='status'){STATE.status=value;STATE.page=1;render()}
  else if(action==='group'){STATE.group=value;render()}
  else if(action==='requirement'||action==='concept'||action==='appendix')openDetail(action,value);
  else if(action==='close')closeDetail();
  else if(action==='clear')resetFilters();
  else if(action==='clear-concept'){STATE.concept=null;STATE.page=1;render()}
  else if(action==='concept-filter'){resetFilters();STATE.concept=value;closeDetail();setView('requirements',true)}
  else if(action==='page'){STATE.page+=Number(value);render();document.getElementById('content').scrollIntoView({block:'start'})}
  else if(action==='export')exportCSV();
  else if(action==='copy')copyConclusion();
  else if(!reviewAction(action,value)&&!arcadeAction(action,value))spaceAction(action,value);
 });
 document.addEventListener('change',e=>{if(['scope','section','confidence','revision','numbering','reviewStatus'].includes(e.target.id)){STATE[e.target.id]=e.target.value;STATE.page=1;SPACE.page=1;render();document.getElementById(e.target.id)?.focus()}});
 let searchTimer;document.getElementById('search').addEventListener('input',e=>{STATE.query=e.target.value;STATE.page=1;REVIEW.page=1;SPACE.page=1;if(STATE.query&&STATE.view==='cosmos'){detachCosmos();SPACE.sector='all';SPACE.concept=null;SPACE.selected=null;SPACE.flight=null;spaceResetCamera()}if(STATE.query&&STATE.view==='map')STATE.group='all';clearTimeout(searchTimer);searchTimer=setTimeout(render,160)});
 document.addEventListener('keydown',e=>{if(e.key==='/'&&STATE.view!=='arcade'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.getElementById('detail').open){e.preventDefault();document.getElementById('search').focus()}});
 document.getElementById('detail').addEventListener('click',e=>{if(e.target===document.getElementById('detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)closeDetail()}});
}


// Independent, append-only analyst opinions. The analytical DATA stays immutable.
const BASIS_ID='cmp-atlas-16a17c22336a89a79ddc46b7';
const REVIEW_KEY='cmpon.reviews.'+BASIS_ID;
const REVIEW_LABELS={question:'Под вопросом',wrong:'Точно неверно',confirmed:'Подтверждаю',withdrawn:'Отозвана'};
const REVIEW_SYMBOL={question:'?',wrong:'×',confirmed:'✓'};
const SOURCE_LABELS={c39:'ФТ сервиса 39',ftt:'ФТТ 57.1'};
const REVIEW={records:[],drafts:{},author:'',clientId:'',storage:true,loadError:false,filter:'all',source:'all',kind:'all',page:1};
function makeReviewId(){return globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)+'-'+Math.random().toString(36).slice(2)}
function reviewKey(kind,id,source){return [kind,id,source].join('|')}
function reviewItem(kind,id){return (kind==='concept'?CONCEPTS:REQS).get(id)}
let reviewCache={records:null,active:[],items:new Map()};
function activeReviews(records=REVIEW.records){if(reviewCache.records===records)return reviewCache.active;const superseded=new Set(records.map(r=>r.supersedes).filter(Boolean)),active=records.filter(r=>!superseded.has(r.id)&&r.status!=='withdrawn'),items=new Map();for(const r of active)for(const key of [reviewKey(r.kind,r.targetId,r.source),reviewKey(r.kind,r.targetId,'')]){if(!items.has(key))items.set(key,[]);items.get(key).push(r)}reviewCache={records,active,items};return active}
function itemReviews(kind,id,source){activeReviews();return reviewCache.items.get(reviewKey(kind,id,source||''))||[]}
function reviewState(kind,id,source){const rs=itemReviews(kind,id,source);return rs.some(r=>r.status==='wrong')?'wrong':rs.some(r=>r.status==='question')?'question':rs.length?'confirmed':'none'}
function hasReviewConflict(rs){const keys=[...new Set(rs.map(r=>reviewKey(r.kind,r.targetId,r.source)))];return keys.some(k=>{const same=rs.filter(r=>reviewKey(r.kind,r.targetId,r.source)===k);return new Set(same.map(r=>r.status)).size>1||new Set(same.map(r=>r.proposed).filter(Boolean)).size>1})}
function missingReview(r){return (STATE.scope==='best'?['c39','ftt']:[STATE.scope]).some(s=>!itemReviews('requirement',r.id,s).length)}
function reviewChip(kind,id,source){const rs=itemReviews(kind,id,source),s=reviewState(kind,id,source);return rs.length?`<span class="review-chip ${s}" title="${attr('Мнение аналитика. '+rs.map(r=>r.author+': '+REVIEW_LABELS[r.status]).join('; '))}">${REVIEW_SYMBOL[s]} ${REVIEW_LABELS[s]}${hasReviewConflict(rs)?' · мнения расходятся':''}</span>`:''}
function matchesReview(r){if(!STATE.reviewStatus||STATE.reviewStatus==='all')return true;const rs=itemReviews('requirement',r.id,STATE.scope==='best'?null:STATE.scope);if(STATE.reviewStatus==='none')return missingReview(r);if(STATE.reviewStatus==='any')return !!rs.length;if(STATE.reviewStatus==='disputed')return rs.some(x=>['question','wrong'].includes(x.status));return rs.some(x=>x.status===STATE.reviewStatus)}
function reviewFilter(){return `<label>Рецензии<select id="reviewStatus">${[['all','Любые'],['disputed','Есть спорные оценки'],['question','Под вопросом'],['wrong','Точно неверно'],['confirmed','Есть подтверждение'],['none','Есть источник без рецензии'],['any','Есть рецензия']].map(([v,t])=>`<option value="${v}"${selectedAttr(v,STATE.reviewStatus||'all')}>${t}</option>`).join('')}</select></label>`}
function validateReviewRecords(records){
 if(!Array.isArray(records)||records.length>20000)throw Error('Некорректное число записей. Допустимо до 20 000.');
 const clean=[],ids=new Set();
 for(const r of records){
  if(!r||typeof r!=='object'||!['requirement','concept'].includes(r.kind)||!reviewItem(r.kind,r.targetId)||!['c39','ftt'].includes(r.source)||!Object.hasOwn(REVIEW_LABELS,r.status))throw Error('Неизвестное требование, источник или статус.');
  for(const [key,max] of [['id',160],['authorId',160],['author',160],['comment',12000],['createdAt',40],['supersedes',160]])if(typeof r[key]!=='string'||r[key].length>max)throw Error('Некорректное поле: '+key);
  if(!r.id||!r.authorId||!r.author.trim()||ids.has(r.id)||!Number.isFinite(Date.parse(r.createdAt))||!['',...CODES].includes(r.proposed)||r.basis!==BASIS_ID)throw Error('Некорректная рецензия или другая редакция анализа.');
  if(['question','wrong'].includes(r.status)&&!r.comment.trim())throw Error('Спорная оценка должна содержать обоснование.');
  const item=reviewItem(r.kind,r.targetId);if(r.original!==item[r.source])throw Error('Исходная оценка отличается от этой редакции атласа.');
  ids.add(r.id);clean.push({id:r.id,kind:r.kind,targetId:r.targetId,source:r.source,status:r.status,proposed:r.proposed,comment:r.comment,author:r.author,authorId:r.authorId,createdAt:r.createdAt,supersedes:r.supersedes,basis:BASIS_ID,original:r.original});
 }
 const byId=new Map(clean.map(r=>[r.id,r]));
 for(const r of clean){if(!r.supersedes)continue;const parent=byId.get(r.supersedes);if(!parent||parent.id===r.id||parent.kind!==r.kind||parent.targetId!==r.targetId||parent.source!==r.source||parent.authorId!==r.authorId)throw Error('Нарушена связь с предыдущей версией рецензии.');const path=new Set([r.id]);let p=parent;while(p){if(path.has(p.id))throw Error('Циклическая история рецензии.');path.add(p.id);p=byId.get(p.supersedes)}}
 return clean;
}
function loadReviews(){
 REVIEW.clientId=makeReviewId();
 try{const raw=localStorage.getItem(REVIEW_KEY);if(!raw)return;const saved=JSON.parse(raw);if(saved.basis!==BASIS_ID)throw Error('Другой анализ');REVIEW.records=validateReviewRecords(saved.records);REVIEW.author=typeof saved.author==='string'?saved.author.slice(0,160):'';REVIEW.clientId=typeof saved.clientId==='string'&&saved.clientId?saved.clientId:REVIEW.clientId;
  if(saved.drafts&&typeof saved.drafts==='object')for(const [k,d] of Object.entries(saved.drafts)){if(k==='__proto__'||!d||typeof d!=='object')continue;const [kind,id,src]=k.split('|');if(!reviewItem(kind,id)||!['requirement','concept'].includes(kind)||!SOURCE_LABELS[src])continue;REVIEW.drafts[k]={status:Object.hasOwn(REVIEW_LABELS,d.status)?d.status:'',proposed:CODES.includes(d.proposed)?d.proposed:'',comment:String(d.comment||'').slice(0,12000),author:String(d.author||'').slice(0,160)}}
 }catch{REVIEW.storage=false;REVIEW.loadError=true}
}
function persistReviews(){
 if(REVIEW.loadError)return false; // Never replace unreadable existing work.
 // Merge committed opinions from another local tab before writing this tab's work.
 try{const raw=localStorage.getItem(REVIEW_KEY);if(raw){const saved=JSON.parse(raw);if(saved.basis!==BASIS_ID)throw Error('Different basis');const remote=validateReviewRecords(saved.records),local=new Map(REVIEW.records.map(r=>[r.id,r]));let added=false;for(const r of remote){if(local.has(r.id)){if(JSON.stringify(local.get(r.id))!==JSON.stringify(r))throw Error('Conflicting record')}else{local.set(r.id,r);added=true}}if(added)REVIEW.records=validateReviewRecords([...local.values()])}}catch{REVIEW.storage=false;REVIEW.loadError=true;return false}
 try{localStorage.setItem(REVIEW_KEY,JSON.stringify({basis:BASIS_ID,records:REVIEW.records,drafts:REVIEW.drafts,author:REVIEW.author,clientId:REVIEW.clientId}));REVIEW.storage=true;return true}catch{REVIEW.storage=false;return false}
}
function storageNotice(){return REVIEW.storage?'Рецензии сохраняются в этом браузере. Для передачи коллегам и резервной копии выгрузите JSON.':REVIEW.loadError?'Не удалось прочитать прежнее хранилище. Оно не перезаписано. Новые рецензии доступны в этой вкладке: обязательно выгрузите JSON.':'Браузер не разрешил сохранение. Рецензии доступны только до закрытия вкладки: обязательно выгрузите JSON.'}
function ownReview(kind,id,source){return itemReviews(kind,id,source).filter(r=>r.authorId===REVIEW.clientId).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0]}
function reviewDate(s){return new Date(s).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function opinionHtml(r){return `<article class="opinion ${r.status}"><div><span class="review-chip ${r.status}">${REVIEW_SYMBOL[r.status]||'↶'} ${REVIEW_LABELS[r.status]}</span><small>${esc(r.author)} · ${reviewDate(r.createdAt)}</small></div>${r.proposed?`<p class="proposal">Предлагает: <b>${LABELS[r.proposed]}</b></p>`:''}${r.comment?`<p class="opinion-comment">${esc(r.comment)}</p>`:''}</article>`}
function reviewEditor(kind,id,source){
 const item=reviewItem(kind,id),rs=itemReviews(kind,id,source),own=ownReview(kind,id,source),key=reviewKey(kind,id,source),draft=REVIEW.drafts[key],values=draft||own||{status:'',proposed:'',comment:'',author:REVIEW.author};
 const prefix='rv-'+kind+'-'+id+'-'+source;
 const history=REVIEW.records.filter(r=>r.kind===kind&&r.targetId===id&&r.source===source);
 return `<div class="review-box" data-review-source="${source}"><div class="review-heading"><b>Мнения аналитиков</b><span>${rs.length?rs.length+' активных':'Пока нет'}</span></div>${hasReviewConflict(rs)?'<p class="review-conflict">Мнения расходятся. Решение о трактовке еще не принято.</p>':''}${rs.map(opinionHtml).join('')}<details class="review-editor"${draft?' open':''}><summary>${own?'Изменить мою рецензию':'Оспорить или подтвердить оценку'} <span>↗</span></summary><form data-review-form data-kind="${kind}" data-target="${id}" data-source="${source}"><p class="review-target">Вы оцениваете вывод «<b>${LABELS[item[source]]}</b>» по ${SOURCE_LABELS[source]}. Оценка в анализе сохранится; ваше мнение появится рядом.</p><label for="${prefix}-author">Ваше имя<input id="${prefix}-author" name="author" type="text" maxlength="160" required autocomplete="name" value="${attr(values.author||REVIEW.author)}" placeholder="Имя и фамилия"></label><fieldset><legend>Ваше решение</legend><div class="review-options">${['question','wrong','confirmed'].map(s=>`<label class="review-choice ${s}"><input type="radio" name="status" value="${s}" required${values.status===s?' checked':''}><span>${REVIEW_SYMBOL[s]} ${REVIEW_LABELS[s]}</span></label>`).join('')}</div></fieldset><label for="${prefix}-proposed">Предлагаемая оценка<select id="${prefix}-proposed" name="proposed"><option value="">Пока не предлагаю замену</option>${CODES.map(s=>`<option value="${s}"${selectedAttr(s,values.proposed)}>${LABELS[s]}</option>`).join('')}</select></label><label for="${prefix}-comment">Обоснование и ссылка на источник<textarea id="${prefix}-comment" name="comment" rows="4" maxlength="12000" placeholder="Что не так в трактовке? Укажите документ, пункт, цитату или недостающее условие.">${esc(values.comment)}</textarea></label><p class="subtle">Для «Под вопросом» и «Точно неверно» обоснование обязательно.</p><div class="review-form-footer"><button class="button primary" type="submit">Сохранить рецензию</button>${own?`<button class="text-button" type="button" data-action="review-withdraw" data-value="${attr(own.id)}">Отозвать мою рецензию</button>`:''}</div><p class="draft-state" data-draft-state role="status">${draft?'Есть черновик. Он еще не добавлен в реестр.':'Имя автора — подпись рецензии, без проверки личности.'}</p><p class="review-error" data-review-error role="alert"></p></form></details>${history.length?`<details class="review-history"><summary>История рецензий · ${history.length}</summary>${history.slice().reverse().map(r=>`<div class="review-history-entry">${opinionHtml(r)}${r.supersedes?'<small>Изменение предыдущей рецензии этого автора</small>':''}</div>`).join('')}</details>`:''}</div>`;
}
function captureDraft(form){const f=form.elements,key=reviewKey(form.dataset.kind,form.dataset.target,form.dataset.source);const d={author:f.author.value.slice(0,160),status:f.status.value,proposed:f.proposed.value,comment:f.comment.value.slice(0,12000)};REVIEW.drafts[key]=d;REVIEW.author=d.author;const ok=persistReviews();const hint=form.querySelector('[data-draft-state]');if(hint)hint.textContent=ok?'Черновик сохранен в этом браузере. Нажмите «Сохранить рецензию».':'Черновик только в этой вкладке. Завершите рецензию и выгрузите JSON.';return d}
function appendOpinion({kind,targetId,source,status,proposed='',comment='',author,supersedes=''}){
 const item=reviewItem(kind,targetId);if(!item||!SOURCE_LABELS[source]||!Object.hasOwn(REVIEW_LABELS,status)||!author?.trim())throw Error('Выберите решение и укажите имя автора.');
 if(['question','wrong'].includes(status)&&!comment.trim())throw Error('Добавьте обоснование: что именно вызывает сомнение или неверно.');
 const r={id:makeReviewId(),kind,targetId,source,status,proposed,comment:comment.trim(),author:author.trim(),authorId:REVIEW.clientId,createdAt:new Date().toISOString(),supersedes,basis:BASIS_ID,original:item[source]};
 const next=validateReviewRecords([...REVIEW.records,r]);REVIEW.records=next;delete REVIEW.drafts[reviewKey(kind,targetId,source)];REVIEW.author=r.author;persistReviews();return r;
}
function saveReviewForm(form){const d=captureDraft(form),{kind,target,source}=form.dataset,own=ownReview(kind,target,source);try{appendOpinion({kind,targetId:target,source,...d,supersedes:own?.id||''});refreshReviewUI(kind,target,source);toast(REVIEW.storage?'Рецензия сохранена в этом браузере':'Рецензия добавлена. Выгрузите JSON до закрытия вкладки.')}catch(e){form.querySelector('[data-review-error]').textContent=e.message}}
function refreshReviewUI(kind,id,source){const dlg=document.getElementById('detail'),top=dlg.scrollTop;render();if(dlg.open&&kind){document.getElementById('detail-body').innerHTML=kind==='concept'?conceptDetail(CONCEPTS.get(id)):requirementDetail(REQS.get(id));dlg.scrollTop=top;if(source)document.querySelector(`[data-review-source="${source}"] summary`)?.focus()}}
function withdrawOpinion(id){const r=REVIEW.records.find(x=>x.id===id);if(!r||r.authorId!==REVIEW.clientId||!activeReviews().some(x=>x.id===id))return;appendOpinion({...r,status:'withdrawn',proposed:'',comment:'Автор отозвал свою рецензию.',supersedes:r.id});refreshReviewUI(r.kind,r.targetId,r.source);toast('Рецензия отозвана. История сохранена.')}
function reviewExport(){return {format:'cmpon-atlas-reviews',version:1,basis:BASIS_ID,exportedAt:new Date().toISOString(),analysisDate:DATA.analyticalRevision.date,sources:DATA.sources.map(s=>({code:s.code,filename:s.filename,sha256:s.sha256})),records:REVIEW.records}}
function mergeReviewPackage(pack){
 if(!pack||pack.format!=='cmpon-atlas-reviews'||pack.version!==1||pack.basis!==BASIS_ID)throw Error('Файл не относится к рецензиям этой редакции атласа.');
 const incoming=validateReviewRecords(pack.records),byId=new Map(REVIEW.records.map(r=>[r.id,r])),added=[];
 for(const r of incoming){if(byId.has(r.id)){if(JSON.stringify(byId.get(r.id))!==JSON.stringify(r))throw Error('Один ID содержит разные записи. Импорт отменен; действующие рецензии сохранены.')}else{added.push(r);byId.set(r.id,r)}}
 const next=validateReviewRecords([...byId.values()]);REVIEW.records=next;persistReviews();return added.length;
}
function downloadFile(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function reviewCSV(){const head=['Тип','Базовый ID','Текущий номер / концепция','Источник','Исходная оценка','Мнение аналитика','Предложенная оценка','Обоснование','Автор','Дата UTC','ID рецензии'];return '\uFEFF'+[head,...filteredReviews().map(r=>[r.kind==='concept'?'Концепция':'Требование',r.targetId,reviewItem(r.kind,r.targetId).number||reviewItem(r.kind,r.targetId).title,SOURCE_LABELS[r.source],LABELS[r.original],REVIEW_LABELS[r.status],LABELS[r.proposed]||'',r.comment,r.author,r.createdAt,r.id])].map(row=>row.map(csvCell).join(';')).join('\r\n')}
function exportReviews(type){if(type==='json'){downloadFile(JSON.stringify(reviewExport(),null,2),'ЦМПОН_рецензии_'+new Date().toISOString().slice(0,10)+'.json','application/json');toast('Выгружены все сохраненные рецензии и их история')}else{downloadFile(reviewCSV(),'ЦМПОН_реестр_рецензий.csv','text/csv;charset=utf-8');toast('Выгружен реестр по действующим фильтрам')}}
async function importReviews(file){if(!file)return;try{if(file.size>25*1024*1024)throw Error('Размер файла превышает 25 МБ.');const pack=JSON.parse((await file.text()).replace(/^\uFEFF/,'')),n=mergeReviewPackage(pack);render();toast(`Добавлено записей: ${n}. Совпадающие записи пропущены.`)}catch(e){const error=document.getElementById('review-import-error');if(error)error.textContent='Импорт не выполнен. '+e.message;toast('Импорт не выполнен. Действующие рецензии сохранены.')}finally{const input=document.getElementById('review-import');if(input)input.value=''}}
function filteredReviews(){return activeReviews().filter(r=>(REVIEW.filter==='all'||(REVIEW.filter==='conflict'?hasReviewConflict(itemReviews(r.kind,r.targetId,r.source)):r.status===REVIEW.filter))&&(REVIEW.source==='all'||r.source===REVIEW.source)&&(REVIEW.kind==='all'||r.kind===REVIEW.kind)&&(!STATE.query||(()=>{const item=reviewItem(r.kind,r.targetId);if(r.kind==='requirement'&&/^(?:ф[тt]|ft)?[\s-]*0*\d+$/i.test(STATE.query))return matchesText(item,STATE.query);return norm(STATE.query).split(' ').every(t=>norm([r.targetId,item.number,item.text,item.title,r.comment,r.author].join(' ')).includes(t))})())).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))}
function reviewTotals(){const active=activeReviews(),req=active.filter(r=>r.kind==='requirement'),keys=new Set(req.map(r=>reviewKey(r.kind,r.targetId,r.source)));return {opinions:active.length,assertions:keys.size,question:new Set(active.filter(r=>r.status==='question').map(r=>reviewKey(r.kind,r.targetId,r.source))).size,wrong:new Set(active.filter(r=>r.status==='wrong').map(r=>reviewKey(r.kind,r.targetId,r.source))).size,confirmed:new Set(active.filter(r=>r.status==='confirmed').map(r=>reviewKey(r.kind,r.targetId,r.source))).size}}
function renderReviews(){const all=filteredReviews(),total=reviewTotals(),pages=Math.max(1,Math.ceil(all.length/30));REVIEW.page=Math.min(REVIEW.page,pages);const rows=all.slice((REVIEW.page-1)*30,REVIEW.page*30);return `<div class="section-title"><div><h2>Рецензирование трактовок</h2><p>Мнения по каждому источнику. Исходные оценки и цитаты остаются доступны.</p></div><span class="review-edition">ОБНОВЛЕНИЕ · 15.10.2026</span></div><div class="review-storage ${REVIEW.storage?'':'failed'}"><b>${REVIEW.storage?'Локальная рабочая копия':'Сохранение ограничено'}</b><p>${storageNotice()}</p><p>Общей синхронизации нет. Импорт объединяет записи без удаления мнений коллег; изменения и отзывы сохраняются в истории.</p></div><div class="review-dashboard"><div><strong>${total.assertions}<small> / 834</small></strong><span>оценок ФТ получили рецензию</span></div><div class="question"><strong>${total.question}</strong><span>оценок под вопросом</span></div><div class="wrong"><strong>${total.wrong}</strong><span>оценок признаны неверными аналитиком</span></div><div><strong>${total.opinions}</strong><span>активных мнений по ФТ и концепциям</span></div></div><p class="subtle">834 = 417 требований × 2 источника. Спорные оценки включают концепции; одна оценка может иметь разные мнения. Рецензия не равна согласованию.</p><div class="review-tools"><button class="button primary" data-action="review-export" data-value="json">${icon('download')} Все рецензии · JSON</button><button class="button" data-action="review-import">${icon('upload')} Загрузить рецензии</button><button class="button" data-action="review-export" data-value="csv">Реестр · CSV</button><input id="review-import" type="file" accept=".json,application/json" hidden></div><p id="review-import-error" class="review-error" role="alert"></p><div class="filters review-filters"><label>Решение<select id="review-filter">${[['all','Все мнения'],['question','Под вопросом'],['wrong','Точно неверно'],['confirmed','Подтверждаю'],['conflict','Мнения расходятся']].map(([v,t])=>`<option value="${v}"${selectedAttr(v,REVIEW.filter)}>${t}</option>`).join('')}</select></label><label>Источник<select id="review-source"><option value="all">Оба источника</option>${Object.entries(SOURCE_LABELS).map(([v,t])=>`<option value="${v}"${selectedAttr(v,REVIEW.source)}>${t}</option>`).join('')}</select></label><label>Объект<select id="review-kind">${[['all','Требования и концепции'],['requirement','Требования'],['concept','Концепции']].map(([v,t])=>`<option value="${v}"${selectedAttr(v,REVIEW.kind)}>${t}</option>`).join('')}</select></label></div><p class="subtle">Поиск сверху — по номеру, тексту, автору и обоснованию. Фильтры покрытия исходных документов к этому реестру не применяются. CSV содержит активные мнения по фильтрам; JSON — всю историю. Черновики не выгружаются.</p>${rows.length?`<div class="review-registry">${rows.map(r=>{const item=reviewItem(r.kind,r.targetId);return `<article class="review-registry-row"><div><button class="req-id" data-action="${r.kind}" data-value="${r.targetId}">${esc(item.number||r.targetId)} ↗</button><small>${SOURCE_LABELS[r.source]} · исходно: ${LABELS[r.original]}</small><p class="registry-title">${esc(item.text||item.title)}</p></div><div>${opinionHtml(r)}${hasReviewConflict(itemReviews(r.kind,r.targetId,r.source))?'<span class="review-conflict">Есть другое мнение</span>':''}</div></article>`}).join('')}</div><div class="page-controls"><span>${all.length} мнений</span><div><button class="button" data-action="review-page" data-value="-1" ${REVIEW.page===1?'disabled':''}>← Назад</button><span>${REVIEW.page} / ${pages}</span><button class="button" data-action="review-page" data-value="1" ${REVIEW.page===pages?'disabled':''}>Далее →</button></div></div>`:`<div class="review-empty"><span>↗</span><h3>${REVIEW.records.length?'Нет мнений по текущим фильтрам':'Начните с одного спорного основания'}</h3><p>Откройте требование или концепцию. Под С39 и ФТТ выберите «Оспорить или подтвердить оценку», укажите решение и обоснование.</p><button class="button primary" data-action="view" data-value="requirements">Открыть требования</button></div>`}`}
function selectedReviewText(){const s=STATE.selected;if(!s||s.kind==='appendix')return '';const rs=itemReviews(s.kind,s.id);return rs.length?'\n\nМНЕНИЯ АНАЛИТИКОВ (не изменяют исходную оценку):\n'+rs.map(r=>`${SOURCE_LABELS[r.source]} · ${REVIEW_LABELS[r.status]} · ${r.author} · ${reviewDate(r.createdAt)}\n${r.proposed?'Предлагаемая оценка: '+LABELS[r.proposed]+'\n':''}${r.comment}`).join('\n\n'):''}
function setupReviews(){
 document.addEventListener('submit',e=>{if(e.target.matches('[data-review-form]')){e.preventDefault();saveReviewForm(e.target)}});
 document.addEventListener('input',e=>{const form=e.target.closest('[data-review-form]');if(form)captureDraft(form)});
 document.addEventListener('change',e=>{const form=e.target.closest('[data-review-form]');if(form)captureDraft(form);if(e.target.id==='review-import')importReviews(e.target.files[0]);const field={'review-filter':'filter','review-source':'source','review-kind':'kind'}[e.target.id];if(field){REVIEW[field]=e.target.value;REVIEW.page=1;render();document.getElementById(e.target.id)?.focus()}});
}
function reviewAction(action,value){if(action==='review-export')exportReviews(value);else if(action==='review-import')document.getElementById('review-import').click();else if(action==='review-withdraw')withdrawOpinion(value);else if(action==='review-page'){REVIEW.page+=Number(value);render()}else return false;return true}

