const GEO_BY_ID=new Map(GEO_LANDS.map(g=>[g.id,g]));
function geoInside(p,poly){let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])yes=!yes}return yes}
function geoEdgeDistance(p,poly){return Math.min(...poly.map((a,i)=>{const b=poly[(i+1)%poly.length],dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy)));return Math.hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy)}))}
function geoBounds(g){const xs=g.points.map(p=>p[0]),ys=g.points.map(p=>p[1]);return {x:Math.min(...xs),y:Math.min(...ys),w:Math.max(...xs)-Math.min(...xs),h:Math.max(...ys)-Math.min(...ys)}}
function geoPath(g){const p=g.points,n=p.length,mid=(a,b)=>[(a[0]+b[0])/2,(a[1]+b[1])/2];return 'M'+mid(p[n-1],p[0]).join(' ')+p.map((a,i)=>'Q'+a.join(' ')+' '+mid(a,p[(i+1)%n]).join(' ')).join('')+'Z'}
const GEO_LAYOUT=new Map(GEO_LANDS.map(g=>{
 const b=geoBounds(g),concepts=DATA.concepts.filter(c=>c.group===g.id),grid=[];
 for(let y=b.y+16;y<b.y+b.h-14;y+=10)for(let x=b.x+16+(Math.round(y)%2)*5;x<b.x+b.w-14;x+=10)if(geoInside([x,y],g.points)&&geoEdgeDistance([x,y],g.points)>18)grid.push([x,y]);
 const cities=[];for(const c of concepts){let bestPoint=null,bestScore=-Infinity;for(const p of grid){const dist=cities.length?Math.min(...cities.map(q=>Math.hypot(q.x-p[0],q.y-p[1]))):-Math.hypot(p[0]-g.center[0],p[1]-g.center[1]);const score=dist+Math.min(geoEdgeDistance(p,g.points),48)*.2;if(score>bestScore){bestPoint=p;bestScore=score}}cities.push({id:c.id,x:bestPoint[0],y:bestPoint[1]})}
 const pins=[],used=new Set();for(const r of DATA.rows.filter(r=>SECTOR_IDS.get(g.id).has(r.id))){const city=cities.find(c=>r.concepts.includes(c.id)),center=city?[city.x,city.y]:g.center;let bestIndex=-1,bestScore=Infinity;grid.forEach((p,i)=>{if(used.has(i)||cities.some(c=>Math.hypot(c.x-p[0],c.y-p[1])<18||(Math.abs(c.x-p[0])<15&&p[1]-c.y>8&&p[1]-c.y<26)))return;const score=Math.hypot(p[0]-center[0],p[1]-center[1]);if(score<bestScore){bestIndex=i;bestScore=score}});if(bestIndex<0)throw Error('Not enough map positions: '+g.id);used.add(bestIndex);pins.push({id:r.id,x:grid[bestIndex][0],y:grid[bestIndex][1],concept:city?.id||null})}
 return [g.id,{cities,pins}];
}));
function spaceRows(){return filteredRows().filter(r=>(['all','overview'].includes(SPACE.sector)||SECTOR_IDS.get(SPACE.sector)?.has(r.id))&&(!SPACE.concept||r.concepts.includes(SPACE.concept))&&(SPACE.review==='all'||(SPACE.review==='unreviewed'?missingReview(r):itemReviews('requirement',r.id,STATE.scope==='best'?null:STATE.scope).some(x=>['question','wrong'].includes(x.status)))))}
function geoGlobalRows(){const sector=SPACE.sector,concept=SPACE.concept;SPACE.sector='all';SPACE.concept=null;const rows=spaceRows();SPACE.sector=sector;SPACE.concept=concept;return rows}
function geoCountryRows(id,rows=geoGlobalRows()){return rows.filter(r=>SECTOR_IDS.get(id).has(r.id))}
function geoCamera(g){if(!g)return {x:0,y:0,w:1200,h:820};const b=geoBounds(g),w=Math.max(b.w+70,(b.h+70)*1200/820);return {x:b.x+b.w/2-w/2,y:b.y+b.h/2-w*820/2400,w,h:w*820/1200}}
function geoClamp(c){c.w=Math.max(220,Math.min(1600,c.w));c.h=c.w*820/1200;c.x=Math.max(-150,Math.min(1350-c.w,c.x));c.y=Math.max(-110,Math.min(930-c.h,c.y));return c}
function spaceResetCamera(){SPACE.camera=geoCamera(GEO_BY_ID.get(SPACE.sector))}
function detachCosmos(){if(SPACE.raf)cancelAnimationFrame(SPACE.raf);SPACE.raf=0}
function updateSpaceCamera(){const s=document.getElementById('universe');if(s)s.setAttribute('viewBox',[SPACE.camera.x,SPACE.camera.y,SPACE.camera.w,SPACE.camera.h].join(' '));const z=document.getElementById('space-zoom-label');if(z)z.textContent=Math.round(1200/SPACE.camera.w*100)+'%'}
function geoFly(target){SPACE.flight={from:{...SPACE.camera},to:geoClamp({...target})};render()}
function geoAnimate(){const flight=SPACE.flight;SPACE.flight=null;if(!flight)return;if(!SPACE.motion||globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches){SPACE.camera=flight.to;updateSpaceCamera();return}let start=null;const frame=time=>{if(STATE.view!=='cosmos'){SPACE.raf=0;return}if(start===null)start=time;const t=Math.min(1,(time-start)/780),a=1-Math.pow(1-t,4);for(const k of ['x','y','w','h'])SPACE.camera[k]=flight.from[k]+(flight.to[k]-flight.from[k])*a;updateSpaceCamera();if(t<1)SPACE.raf=requestAnimationFrame(frame);else SPACE.raf=0};SPACE.raf=requestAnimationFrame(frame)}
function spaceZoom(factor){if(!Number.isFinite(factor)||factor<=0)return;detachCosmos();SPACE.flight=null;const c=SPACE.camera,w=Math.max(220,Math.min(1600,c.w/factor)),h=w*820/1200;SPACE.camera=geoClamp({x:c.x+(c.w-w)/2,y:c.y+(c.h-h)/2,w,h});updateSpaceCamera()}
function geoSvgDefs(){return `<defs><linearGradient id="geo-sea" x2="1" y2="1"><stop stop-color="#143c46"/><stop offset=".55" stop-color="#10343b"/><stop offset="1" stop-color="#08262d"/></linearGradient><pattern id="geo-grid" width="50" height="50" patternUnits="userSpaceOnUse"><path d="M50 0H0V50" fill="none" stroke="#c6e9e3" stroke-opacity=".07" stroke-width=".7"/></pattern><pattern id="geo-grain" width="6" height="6" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".55" fill="#193f3e" opacity=".14"/></pattern>${GEO_LANDS.map(g=>`<linearGradient id="land-${g.id}" x2=".8" y2="1"><stop stop-color="#f0ead2"/><stop offset=".46" stop-color="${g.color}"/><stop offset="1" stop-color="${g.color}"/></linearGradient><clipPath id="clip-${g.id}"><path d="${geoPath(g)}"/></clipPath>`).join('')}<symbol id="geo-tree" viewBox="0 0 10 14"><path d="M5 0 0 8h3l-2 3h3v3h2v-3h3L7 8h3Z" fill="#244d43"/></symbol><symbol id="geo-house" viewBox="0 0 20 24"><path d="m2 10 8-5 8 5v10l-8 4-8-4Z" fill="#f7edd2"/><path d="m10 14 8-4v10l-8 4Z" fill="#56796e"/><path d="m0 10 10-10 10 10-10 5Z" fill="#304f49"/><path d="M5 15v4m7-2v3" stroke="#ae7649" stroke-width="2"/></symbol></defs>`}
function geoContours(g){const [x,y]=g.center;return `<g clip-path="url(#clip-${g.id})" aria-hidden="true">${[.45,.68,.92,1.15,1.38].map((s,i)=>`<path d="${geoPath(g)}" transform="translate(${x} ${y}) scale(${s}) translate(${-x+8*i} ${-y+3*i})" fill="none" stroke="#33594c" stroke-opacity="${.11-i*.012}" stroke-width="1.1"/>`).join('')}<path d="M${x-130} ${y-90}Q${x-15} ${y+70} ${x+130} ${y+15}" fill="none" stroke="#608f86" stroke-width="2" opacity=".32"/>${Array.from({length:14},(_,i)=>{const p=[x+Math.sin(i*3.83)*140,y+Math.cos(i*1.77)*100];return geoInside(p,g.points)?`<use href="#geo-tree" x="${p[0]}" y="${p[1]}" width="7" height="10" opacity=".2"/>`:''}).join('')}</g>`}
function geoCountry(g,i,available){const path=geoPath(g),active=SPACE.sector===g.id,detail=!['overview','all'].includes(SPACE.sector),rows=geoCountryRows(g.id,available),c=counts(rows),visible=new Set(rows.map(r=>r.id));const rv=rows.filter(r=>['question','wrong'].includes(reviewState('requirement',r.id,STATE.scope==='best'?null:STATE.scope))).length;return `<g class="geo-country ${detail&&!active?'geo-muted':''} ${active?'geo-active':''}" data-country="${g.id}"><path d="${path}" transform="translate(0 12)" fill="#041a1e" opacity=".55"/><path d="${path}" fill="none" stroke="#91c3bb" stroke-width="27" opacity=".06"/><path d="${path}" fill="none" stroke="#a3d1c8" stroke-width="13" opacity=".1"/><path d="${path}" transform="translate(0 5)" fill="#54746b"/><path class="geo-land" d="${path}" fill="url(#land-${g.id})" stroke="#e7e3cb" stroke-width="1.5"/><path d="${path}" fill="url(#geo-grain)"/>${geoContours(g)}${geoLocalLinks(g,active)}${GEO_LAYOUT.get(g.id).pins.map(p=>{const r=REQS.get(p.id),isVisible=visible.has(r.id)&&(!SPACE.concept||r.concepts.includes(SPACE.concept)),selected=r.id===SPACE.selected,review=reviewState('requirement',r.id,STATE.scope==='best'?null:STATE.scope);return `<g class="geo-pin ${selected?'geo-pin-selected':''}" ${active&&isVisible?`data-action="space-select" data-value="${r.id}" role="button" tabindex="0" aria-label="${attr(r.number+' · '+LABELS[statusOf(r)])}"`:''} opacity="${isVisible?1:.12}"><title>${esc(r.number+' · '+r.text)}</title>${active&&isVisible?`<circle cx="${p.x}" cy="${p.y}" r="6" fill="transparent"/>`:''}${selected?`<circle class="geo-pulse" cx="${p.x}" cy="${p.y}" r="9" fill="none" stroke="#fff7cf" stroke-width="2"/>`:''}<circle cx="${p.x}" cy="${p.y}" r="${selected?4.8:active?3.2:1.9}" fill="${SPACE_COLORS[statusOf(r)]}" stroke="${selected?'#fff7cf':'#e9ead7'}" stroke-width="${selected?1.7:.6}"/>${active&&['question','wrong'].includes(review)?`<text x="${p.x+4}" y="${p.y-3}" class="geo-review-mark">${review==='wrong'?'×':'?'}</text>`:''}${selected&&active?`<g class="geo-pin-label"><rect x="${p.x-26}" y="${p.y-23}" width="52" height="13" rx="3" fill="#0c3339"/><text x="${p.x}" y="${p.y-14}" text-anchor="middle" fill="#fff5d5" font-size="7.5" font-weight="700">${esc(r.number)}</text></g>`:''}</g>`}).join('')}${active?GEO_LAYOUT.get(g.id).cities.map(city=>{const concept=CONCEPTS.get(city.id),n=concept.requirements.filter(id=>visible.has(id)).length,selected=SPACE.concept===city.id;return `<g class="geo-city ${selected?'chosen':''}" opacity="${SPACE.concept&&!selected?.4:1}" data-action="space-concept" data-value="${city.id}" role="button" tabindex="0" aria-label="${attr(city.id+' '+concept.title+'; '+n+' ФТ по фильтрам')}"><title>${esc(concept.title)} · ${n} ФТ по фильтрам</title><circle cx="${city.x}" cy="${city.y}" r="11" fill="#f7edcb" stroke="#3a6057" stroke-width=".6"/><use href="#geo-house" x="${city.x-6}" y="${city.y-10}" width="12" height="15"/><text x="${city.x}" y="${city.y+20}" text-anchor="middle" font-size="8" font-weight="700" fill="#173d3b">${city.id}</text></g>`}).join(''):`<g class="geo-country-target" data-action="space-sector" data-value="${g.id}" role="button" tabindex="0" aria-label="${attr(SPACE_SECTORS.find(s=>s.id===g.id).title+'; '+rows.length+' требований')}"><path d="${path}" fill="transparent"/><g class="geo-country-label" transform="translate(${g.center[0]} ${g.center[1]-10})"><rect x="-106" y="-29" width="212" height="${g.name.length>1?90:72}" rx="12" fill="#f5efda" fill-opacity=".94"/><text y="-11" text-anchor="middle" class="geo-country-code">${String(i+1).padStart(2,'0')} / ${DATA.concepts.filter(c=>c.group===g.id).length} КОНЦЕПЦИЙ</text>${g.name.map((s,j)=>`<text y="${12+j*19}" text-anchor="middle" class="geo-country-title">${esc(s)}</text>`).join('')}<text y="${g.name.length>1?51:33}" text-anchor="middle" class="geo-country-count">${rows.length} ФТ${rv?' · '+rv+' спорных':''}</text></g></g>`}</g>`}
function geoLocalLinks(g,active){if(!active||!SPACE.links||!SPACE.concept)return '';const city=GEO_LAYOUT.get(g.id).cities.find(c=>c.id===SPACE.concept);if(!city)return '';const ids=new Set(spaceRows().map(r=>r.id));return '<g aria-hidden="true" pointer-events="none">'+GEO_LAYOUT.get(g.id).pins.filter(p=>ids.has(p.id)).map(p=>`<path d="M${city.x} ${city.y}Q${city.x} ${p.y} ${p.x} ${p.y}" fill="none" stroke="#8b7048" stroke-width=".65" stroke-dasharray="2 3" opacity=".5" class="geo-route"/>`).join('')+'</g>'}
function geoRoutes(available){if(!SPACE.links)return '';const chosen=REQS.get(SPACE.selected),countries=GEO_LANDS.filter(g=>chosen?SECTOR_IDS.get(g.id).has(chosen.id):true),paths=[];for(let i=0;i<countries.length;i++)for(let j=i+1;j<countries.length;j++){const a=countries[i],b=countries[j],shared=chosen?1:available.filter(r=>SECTOR_IDS.get(a.id).has(r.id)&&SECTOR_IDS.get(b.id).has(r.id)).length;if(!shared||(!chosen&&shared<5))continue;const [x,y]=a.center,[xx,yy]=b.center;paths.push(`<path class="geo-route ${chosen?'geo-route-selected':''}" d="M${x} ${y}Q${(x+xx)/2+30} ${(y+yy)/2-80} ${xx} ${yy}" fill="none" stroke="${chosen?'#f8d993':'#a6d1c3'}" stroke-width="${chosen?2:1}" stroke-dasharray="${chosen?'5 5':'3 9'}" opacity="${chosen?.8:.2}"><title>${chosen?esc(chosen.number)+': связь тем':shared+' общих ФТ'}</title></path>`)}return paths.join('')}
function geoCompass(){return `<g transform="translate(1120 75)" aria-hidden="true" fill="none" stroke="#b9d3c5" opacity=".7"><circle r="23" stroke-opacity=".3"/><path d="M0-30 5 0 0 30-5 0Z"/><path d="M-30 0H30M0-30V30" stroke-opacity=".3"/><path d="M0-30 5 0H0Z" fill="#d9cba1"/><text y="-38" text-anchor="middle" fill="#c9dbd0" stroke="none" font-size="10">N</text></g>`}
function geoMapSvg(){const available=geoGlobalRows();return `<svg id="universe" class="geo-map-svg" xmlns="http://www.w3.org/2000/svg" viewBox="${[SPACE.camera.x,SPACE.camera.y,SPACE.camera.w,SPACE.camera.h].join(' ')}" role="group" aria-label="География требований. Страны — темы, города — концепции, точки — ФТ. Масштаб: плюс и минус. Перемещение: стрелки или перетаскивание фона." tabindex="0">${geoSvgDefs()}<rect x="-500" y="-500" width="2200" height="1820" fill="url(#geo-sea)"/><rect x="-500" y="-500" width="2200" height="1820" fill="url(#geo-grid)"/><g aria-hidden="true" class="geo-currents"><path d="M-60 380Q240 400 450 315T1220 400M-60 390Q240 410 450 325T1220 410M-60 400Q240 420 450 335T1220 420" fill="none" stroke="#b3d2c2" stroke-opacity=".13" stroke-width=".8"/></g><text x="48" y="43" fill="#c5dacd" font-size="11" letter-spacing="4" font-family="sans-serif" opacity=".6">ЦМПОН / ТЕМАТИЧЕСКИЙ АРХИПЕЛАГ</text>${GEO_LANDS.map((g,i)=>geoCountry(g,i,available)).join('')}<g class="geo-routes" aria-hidden="true" pointer-events="none">${geoRoutes(available)}</g>${geoCompass()}<text x="1015" y="759" text-anchor="middle" fill="#b2cfc6" opacity=".5" font-size="10" letter-spacing="3">МОРЕ ОСНОВАНИЙ</text><text x="1015" y="780" text-anchor="middle" fill="#b2cfc6" opacity=".45" font-size="9">С39 · ЦМПОН · ФТТ 57.1</text></svg>`}
function geoProgress(rows){const source=STATE.scope==='best'?null:STATE.scope,max=rows.length*(source?1:2),done=rows.reduce((n,r)=>n+['c39','ftt'].filter(s=>(!source||s===source)&&itemReviews('requirement',r.id,s).length).length,0);return {done,max}}
function geoDossier(rows){const r=REQS.get(SPACE.selected);if(r&&rows.some(x=>x.id===r.id))return `<aside class="geo-dossier" id="geo-dossier" tabindex="-1"><p class="geo-eyebrow">ПАСПОРТ ТРЕБОВАНИЯ <button data-action="space-deselect" aria-label="Снять выбор требования">×</button></p><h3>${esc(r.number)} <small>база ${esc(r.id)}</small></h3><p class="geo-requirement">${esc(r.text)}</p><div class="geo-memberships">${SPACE_SECTORS.filter(g=>SECTOR_IDS.get(g.id).has(r.id)).map(g=>`<button data-action="space-follow" data-value="${g.id}" title="Показать это требование в теме">${esc(g.title)} ↗</button>`).join('')}</div>${['c39','ftt'].map(s=>`<div class="geo-evidence"><div><b>${s==='c39'?'ФТ сервиса 39':'ФТТ 57.1'}</b>${badge(r[s])}</div><small>Достоверность: ${esc(r[s+'Confidence'].toLowerCase())}</small>${reviewChip('requirement',r.id,s)}<button data-action="space-review" data-value="${s}">Проверить / оспорить ↗</button></div>`).join('')}<button class="geo-button geo-primary" data-action="space-open" data-value="${r.id}">Текст и цитаты источников ↗</button><button class="geo-button" data-action="space-next" data-value="next">Следующее требование →</button></aside>`;
 const country=SPACE_SECTORS.find(g=>g.id===SPACE.sector),concept=CONCEPTS.get(SPACE.concept),cs=counts(rows),p=geoProgress(rows);return `<aside class="geo-dossier" id="geo-dossier" tabindex="-1"><p class="geo-eyebrow">${concept?'КОНЦЕПЦИЯ '+concept.id:country?'ПАСПОРТ ТЕМЫ':'ЭКСПЕДИЦИЯ ПО ОСНОВАНИЯМ'}</p><h3>${esc(concept?.title||country?.title||'У каждого ФТ — своё место.')}</h3><p class="geo-explainer">${concept?'Ниже — связанные требования. Откройте основание концепции, чтобы проверить общий вывод.':country?'Города обозначают концепции, цветные точки — связанные требования. Выбирайте их на карте или в списке.':'Выберите страну, затем город-концепцию или точку требования. Цвет точки показывает оценку по выбранному источнику.'}</p>${concept?`<button class="geo-button geo-primary" data-action="concept" data-value="${concept.id}">Основания концепции ↗</button>`:''}<div class="geo-total"><b>${rows.length}</b><span>уникальных ФТ<br>по текущим фильтрам</span></div><div class="geo-distribution">${CODES.map(s=>`<span style="width:${rows.length?cs[s]/rows.length*100:0}%;background:${SPACE_COLORS[s]}" title="${LABELS[s]}: ${cs[s]}"></span>`).join('')}</div><div class="geo-counts">${CODES.map(s=>`<button data-action="space-status" data-value="${s}"><i style="background:${SPACE_COLORS[s]}"></i>${SHORT[s]}<b>${cs[s]}</b></button>`).join('')}</div><div class="geo-progress"><span>Источников с рецензией <b>${p.done} / ${p.max}</b></span><progress value="${p.done}" max="${p.max||1}"></progress><small>Просмотр карточки не считается рецензией.</small></div><button class="geo-button geo-primary" data-action="space-next" data-value="unreviewed">К ФТ без рецензии →</button><button class="geo-button" data-action="space-next" data-value="disputed">Разобрать спорное →</button><p class="geo-footnote">Карта показывает связи тем и оценки текстов. Это условная география, а не схема контуров или потоков данных.</p></aside>`}
function geoConcepts(){const cs=DATA.concepts.filter(c=>c.group===SPACE.sector),visible=new Set(geoGlobalRows().map(r=>r.id));return `<div class="geo-concepts"><div class="geo-list-title"><span>${cs.length?'ГОРОДА / КОНЦЕПЦИИ':'СТРАНЫ / ТЕМЫ'}</span><b>${cs.length||9}</b></div>${cs.length?`<button class="geo-concept ${!SPACE.concept?'active':''}" data-action="space-concept" data-value="all"><b>Вся страна</b><span>Все требования темы →</span></button>${cs.map(c=>`<button class="geo-concept ${SPACE.concept===c.id?'active':''}" data-action="space-concept" data-value="${c.id}"><small>${c.id} <span>${c.requirements.filter(id=>visible.has(id)).length} ФТ</span></small><b>${esc(c.title)}</b>${reviewChip('concept',c.id)}</button>`).join('')}`:SPACE_SECTORS.map((g,i)=>`<button class="geo-concept ${SPACE.sector===g.id?'active':''}" data-action="space-sector" data-value="${g.id}"><small>СТРАНА ${String(i+1).padStart(2,'0')}<span>${geoCountryRows(g.id).length} ФТ</span></small><b>${esc(g.title)}</b></button>`).join('')}</div>`}
function geoLedger(rows){const slice=rows.slice((SPACE.page-1)*24,SPACE.page*24);return `<section class="geo-ledger"><div class="geo-ledger-head"><div><p class="geo-eyebrow">ТОЧКИ НА КАРТЕ</p><h3>${SPACE.concept?esc(CONCEPTS.get(SPACE.concept).title):'Требования выбранной территории'}</h3></div><span>${rows.length} ФТ</span></div><div class="geo-ledger-grid">${geoConcepts()}<div class="geo-results"><div class="geo-results-status" role="status" aria-live="polite">${rows.length?`${(SPACE.page-1)*24+1}–${Math.min(SPACE.page*24,rows.length)} из ${rows.length} ФТ`:'Требования не найдены'} · ${esc(scopeName())}${STATE.query?' · Поиск: '+esc(STATE.query):''}</div>${rows.length?`<div class="geo-result-list">${slice.map(r=>`<button class="geo-result ${r.id===SPACE.selected?'active':''}" data-action="space-select" data-value="${r.id}" aria-pressed="${r.id===SPACE.selected}"><span><b>${esc(r.number)}</b><i style="background:${SPACE_COLORS[statusOf(r)]}"></i><small>${SHORT[statusOf(r)]}</small></span><p>${esc(r.text)}</p><small>С39: ${SHORT[r.c39]} · ФТТ: ${SHORT[r.ftt]}</small>${reviewChip('requirement',r.id)}</button>`).join('')}</div><div class="geo-pagination"><button class="geo-button" data-action="space-page" data-value="-1" ${SPACE.page===1?'disabled':''}>← Назад</button><span>${SPACE.page} / ${Math.ceil(rows.length/24)}</span><button class="geo-button" data-action="space-page" data-value="1" ${SPACE.page*24>=rows.length?'disabled':''}>Далее →</button></div>`:`<div class="geo-empty"><b>${SPACE.concept&&CONCEPTS.get(SPACE.concept).requirements.length===0?'У концепции нет связанных ФТ':'По этим фильтрам нет требований'}</b><p>${SPACE.concept&&CONCEPTS.get(SPACE.concept).requirements.length===0?'Откройте основания концепции: её оценка доступна отдельно.':'Измените поиск, оценку или фильтр рецензий.'}</p>${SPACE.concept?`<button class="geo-button" data-action="concept" data-value="${SPACE.concept}">Открыть концепцию ↗</button>`:''}<button class="geo-button" data-action="space-clear">Сбросить фильтры</button></div>`}</div></div></section>`}
function renderCosmos(){const rows=spaceRows();SPACE.page=Math.min(Math.max(1,SPACE.page),Math.max(1,Math.ceil(rows.length/24)));if(SPACE.selected&&!rows.some(r=>r.id===SPACE.selected))SPACE.selected=null;const country=SPACE_SECTORS.find(g=>g.id===SPACE.sector);return `<section class="geography ${SPACE.motion?'':'geo-motion-off'}"><header class="geo-heading"><div><p class="geo-eyebrow">ЦМПОН / ИНТЕРАКТИВНАЯ ГЕОКАРТА</p><h2>География <em>требований.</em></h2><p>От общей территории — к точной формулировке и её основанию.</p></div><div class="geo-edition"><b>417<span>ФТ</span></b><small>8 тематических стран<br>50 концепций</small></div></header><div class="geo-tour"><span><b>01</b> Выберите страну</span><i>→</i><span><b>02</b> Найдите концепцию или ФТ</span><i>→</i><span><b>03</b> Проверьте источник</span></div><div class="geo-toolbar"><nav class="geo-breadcrumb" aria-label="Положение на геокарте"><button data-action="space-sector" data-value="overview">Весь архипелаг</button>${country?`<span>/</span><button data-action="space-sector" data-value="${country.id}">${esc(country.title)}</button>`:SPACE.sector==='all'?'<span>/</span><b>Все требования</b>':''}${SPACE.concept?`<span>/</span><b>${SPACE.concept}</b>`:''}</nav><div class="geo-tools"><label>Рецензии<select id="space-review-filter"><option value="all"${selectedAttr(SPACE.review,'all')}>Все</option><option value="disputed"${selectedAttr(SPACE.review,'disputed')}>Есть спорные</option><option value="unreviewed"${selectedAttr(SPACE.review,'unreviewed')}>Есть непроверенный источник</option></select></label><button class="geo-button ${SPACE.links?'active':''}" data-action="space-links" aria-pressed="${SPACE.links}" title="Связи по общим требованиям">Связи</button><button class="geo-button" data-action="space-motion" aria-pressed="${SPACE.motion}" title="Анимация карты">${SPACE.motion?'Ⅱ Анимация':'▷ Анимация'}</button></div></div><div class="geo-explorer"><div class="geo-map-column"><div class="geo-map-frame"><div class="geo-map-badge"><i></i>${country?esc(country.title):'АРХИПЕЛАГ ТРЕБОВАНИЙ'}<span>${rows.length} ФТ по фильтрам</span></div>${geoMapSvg()}<div class="geo-map-controls"><button data-action="space-zoom" data-value="1.3" aria-label="Приблизить карту">+</button><button data-action="space-zoom" data-value="0.77" aria-label="Отдалить карту">−</button><button data-action="space-fit" aria-label="Вписать выбранную территорию" title="Вписать территорию">⌖</button><span id="space-zoom-label">${Math.round(1200/SPACE.camera.w*100)}%</span></div><span class="geo-map-hint">Перетаскивайте фон · Ctrl + колесо — масштаб</span></div><div class="geo-map-caption"><span>Страна — тема · город — концепция · точка — ФТ</span><button data-action="space-sector" data-value="all">Все 417 в списке ↗</button></div><div class="geo-legend"><span>ЦВЕТ ТОЧКИ</span>${CODES.map(s=>`<button class="${STATE.status===s?'active':''}" data-action="space-status" data-value="${s}" aria-pressed="${STATE.status===s}"><i style="background:${SPACE_COLORS[s]}"></i>${LABELS[s]}</button>`).join('')}<button class="${STATE.status==='all'?'active':''}" data-action="space-status" data-value="all">Все</button></div><p class="geo-overlap">Точка показана один раз внутри темы; выбор города подсвечивает все связанные с ним ФТ. Темы пересекаются, их числа не суммируются. Линии внутри страны связывают выбранную концепцию с ФТ, между странами — темы с общими ФТ${SPACE.selected?' выбранного требования':'; в общем виде — от 5 общих ФТ'}. ? — под вопросом, × — неверно по мнению аналитика.</p></div>${geoDossier(rows)}</div>${geoLedger(rows)}<div class="geo-bottom"><p>Точная трактовка остаётся предметом проверки. Рецензии на карте и в реестре — общие.</p><button class="geo-button" data-action="view" data-value="reviews">Реестр рецензий ↗</button></div></section>`}
function setSpaceSector(value){if(!['overview','all',...SPACE_SECTORS.map(x=>x.id)].includes(value))return;SPACE.sector=value;SPACE.concept=null;SPACE.page=1;SPACE.selected=null;geoFly(geoCamera(GEO_BY_ID.get(value)))}
function geoSelect(id){const r=REQS.get(id);if(!r||!spaceRows().some(x=>x.id===id))return;if(['overview','all'].includes(SPACE.sector)){SPACE.sector=SPACE_SECTORS.find(g=>SECTOR_IDS.get(g.id).has(id)).id;SPACE.concept=null}SPACE.selected=id;SPACE.page=Math.floor(spaceRows().findIndex(r=>r.id===id)/24)+1;geoFly(geoCamera(GEO_BY_ID.get(SPACE.sector)));document.getElementById('geo-dossier')?.focus({preventScroll:true});if(globalThis.matchMedia?.('(max-width: 760px)').matches)document.getElementById('geo-dossier')?.scrollIntoView({block:'start',behavior:SPACE.motion?'smooth':'auto'})}
function spacePickNext(mode){let rows=spaceRows();if(mode==='disputed')rows=rows.filter(r=>itemReviews('requirement',r.id,STATE.scope==='best'?null:STATE.scope).some(x=>['question','wrong'].includes(x.status)));if(mode==='unreviewed')rows=rows.filter(missingReview);if(!rows.length){toast(mode==='disputed'?'По текущим фильтрам спорных требований нет':'По текущим фильтрам подходящих требований нет');return}const next=rows[(rows.findIndex(r=>r.id===SPACE.selected)+1)%rows.length];geoSelect(next.id)}
function openSpaceReview(source){if(!SPACE.selected)return;openDetail('requirement',SPACE.selected);const box=document.querySelector(`[data-review-source="${source}"]`);if(box){box.querySelector('.review-editor').open=true;box.scrollIntoView({block:'start'});box.querySelector('input')?.focus({preventScroll:true})}}
function spaceAction(action,value){
 if(action==='space-sector')setSpaceSector(value);
 else if(action==='space-select')geoSelect(value);
 else if(action==='space-deselect'){SPACE.selected=null;render()}
 else if(action==='space-follow'){const id=SPACE.selected;if(!GEO_BY_ID.has(value)||!id||!SECTOR_IDS.get(value).has(id))return;SPACE.sector=value;SPACE.concept=null;SPACE.page=Math.floor(spaceRows().findIndex(r=>r.id===id)/24)+1;geoFly(geoCamera(GEO_BY_ID.get(value)))}
 else if(action==='space-concept'){const c=CONCEPTS.get(value);if(value!=='all'&&(!c||c.group!==SPACE.sector))return;SPACE.concept=value==='all'?null:value;SPACE.selected=null;SPACE.page=1;geoFly(geoCamera(GEO_BY_ID.get(SPACE.sector)))}
 else if(action==='space-open'&&REQS.has(value))openDetail('requirement',value);
 else if(action==='space-review'&&['c39','ftt'].includes(value))openSpaceReview(value);
 else if(action==='space-status'&&(value==='all'||CODES.includes(value))){STATE.status=value;SPACE.page=1;render()}
 else if(action==='space-next')spacePickNext(value);
 else if(action==='space-page'){SPACE.page+=Number(value);render()}
 else if(action==='space-zoom')spaceZoom(Number(value));
 else if(action==='space-fit')geoFly(geoCamera(GEO_BY_ID.get(SPACE.sector)));
 else if(action==='space-motion'){SPACE.motion=!SPACE.motion;if(!SPACE.motion&&SPACE.flight){SPACE.camera=SPACE.flight.to;SPACE.flight=null}render()}
 else if(action==='space-links'){SPACE.links=!SPACE.links;render()}
 else if(action==='space-clear'){SPACE.review='all';SPACE.concept=null;SPACE.page=1;resetFilters()}
}
function mountCosmos(){const svg=document.getElementById('universe');if(!svg)return;let drag=null;
 svg.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('[data-action]'))return;detachCosmos();SPACE.flight=null;const rect=svg.getBoundingClientRect(),scale=Math.min(rect.width/SPACE.camera.w,rect.height/SPACE.camera.h);drag={id:e.pointerId,x:e.clientX,y:e.clientY,cam:{...SPACE.camera},scale};svg.setPointerCapture?.(e.pointerId);svg.classList.add('dragging')});
 svg.addEventListener('pointermove',e=>{if(!drag||(e.pointerId!==undefined&&e.pointerId!==drag.id))return;SPACE.camera=geoClamp({...drag.cam,x:drag.cam.x-(e.clientX-drag.x)/drag.scale,y:drag.cam.y-(e.clientY-drag.y)/drag.scale});updateSpaceCamera()});
 const end=()=>{drag=null;svg.classList.remove('dragging')};for(const type of ['pointerup','pointercancel','lostpointercapture'])svg.addEventListener(type,end);
 svg.addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();spaceZoom(e.deltaY<0?1.12:1/1.12)},{passive:false});
 svg.addEventListener('keydown',e=>{const b=e.target.closest('[data-action]');if(b&&['Enter',' '].includes(e.key)){e.preventDefault();spaceAction(b.dataset.action,b.dataset.value);return}if(e.target!==svg)return;const c=SPACE.camera;if(e.key==='+'||e.key==='='){e.preventDefault();spaceZoom(1.25)}else if(e.key==='-'){e.preventDefault();spaceZoom(.8)}else if(e.key==='Home'){e.preventDefault();geoFly(geoCamera(GEO_BY_ID.get(SPACE.sector)))}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();detachCosmos();c.x+=e.key==='ArrowLeft'?-c.w*.08:e.key==='ArrowRight'?c.w*.08:0;c.y+=e.key==='ArrowUp'?-c.h*.08:e.key==='ArrowDown'?c.h*.08:0;SPACE.camera=geoClamp(c);updateSpaceCamera()}});geoAnimate();
}
function setupCosmos(){SPACE.motion=!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;document.addEventListener('change',e=>{if(e.target.id==='space-review-filter'&&['all','disputed','unreviewed'].includes(e.target.value)){SPACE.review=e.target.value;SPACE.page=1;SPACE.selected=null;render()}})}

// Цитадель ЦСИИ. Pure 3D flight simulation; atlas data is read-only.
const ARCADE_SECTORS=[
 {id:'architecture',title:'Периметр Цитадели',brief:'Верните три модуля ФТ и зачистите орбиту базы.',color:'#64e9f5',quota:7},
 {id:'sampling',title:'Пояс астероидов',brief:'Пройдите сквозь астероиды и заберите модули выборок и ЛПХ.',color:'#9befbb',quota:9},
 {id:'demography',title:'Туманность данных',brief:'Перехватите дроны и восстановите три модуля демографии.',color:'#ffc38b',quota:11},
 {id:'process',title:'Последний рубеж',brief:'Соберите модули и уничтожьте крейсер «Бесконечное согласование».',color:'#c7a3ff',quota:10}
];
function arcadeSeed(seed){let n=seed>>>0;const next=()=>{n=(n*1664525+1013904223)>>>0;return n/4294967296};next.getState=()=>n;return next}
function arcadeClamp(v,a,b){return Math.max(a,Math.min(b,v))}
function arcadePlan(seed){const random=arcadeSeed(seed),used=new Set();return ARCADE_SECTORS.map(s=>{const a=[...(SECTOR_IDS.get(s.id)||[])].filter(id=>REQS.has(id)&&!used.has(id));for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}const picked=a.slice(0,3);picked.forEach(id=>used.add(id));return picked})}
const V3={add:(a,b)=>[a[0]+b[0],a[1]+b[1],a[2]+b[2]],sub:(a,b)=>[a[0]-b[0],a[1]-b[1],a[2]-b[2]],scale:(a,s)=>[a[0]*s,a[1]*s,a[2]*s],dot:(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2],cross:(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],len:a=>Math.hypot(...a),norm:a=>{const n=Math.hypot(...a);return n>1e-8?a.map(v=>v/n):[0,0,-1]},lerp:(a,b,t)=>a.map((v,i)=>v+(b[i]-v)*t)};
function flightBasis(yaw,pitch,bank=0){const f=[Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch)],r=[Math.cos(yaw),0,Math.sin(yaw)],u=V3.cross(r,f),c=Math.cos(bank),s=Math.sin(bank);return {f,r:V3.add(V3.scale(r,c),V3.scale(u,s)),u:V3.add(V3.scale(u,c),V3.scale(r,-s))}}
function flightSegment(a,b,p,r){const d=V3.sub(b,a),den=V3.dot(d,d),t=den?arcadeClamp(V3.dot(V3.sub(p,a),d)/den,0,1):0;return V3.len(V3.sub(V3.add(a,V3.scale(d,t)),p))<=r?t:null}
const FLIGHT_ENEMIES={scout:{hp:32,r:2.7,speed:19,points:100,color:'#fb836c',name:'Перехватчик'},hunter:{hp:55,r:3.4,speed:15,points:160,color:'#f1bd6b',name:'Охотник'},heavy:{hp:100,r:4.4,speed:10,points:240,color:'#b69bff',name:'Тяжёлый дрон'}};
class CitadelFlightBase{
 constructor(seed=Date.now(),emit=()=>{}){this.seed=seed>>>0;this.random=arcadeSeed(seed);this.emit=emit;this.plan=arcadePlan(seed);this.status='menu';this.stage=0;this.assist=false;this.score=0;this.rescued=[];this.lastRescued=null;this.elapsed=0;this.totalKills=0;this.shots=0;this.hits=0;this.combo=0;this.maxCombo=0;this.comboTime=0;this.player={pos:[0,0,0],yaw:0,pitch:0,bank:0,hp:100,energy:100,speed:20,invulnerable:0,shotCooldown:0,missileCooldown:0,missiles:6,pulseCooldown:0,flipCooldown:0,boosting:false};this.stageKills=0;this.stageTime=0;this.enemies=[];this.bullets=[];this.hostile=[];this.pickups=[];this.particles=[];this.trails=[];this.boss=null;this.bossDefeated=false;this.entityId=0;this.flash=0;this.shake=0;this.hitFlash=0;this.spawnClock=3;this.pulseWave=0;this.lock=null;this.warning='';this.setupWorld(0)}
 setupWorld(stage){const rnd=arcadeSeed(this.seed+stage*571),positions=[[0,0,-67],[65,20,-155],[-68,-17,-245]];this.pickups=this.plan[stage].map((reqId,i)=>({type:'requirement',reqId,pos:positions[i].slice(),r:8,dead:false}));this.asteroids=[];for(let i=0;i<65+stage*12;i++){let pos=[(rnd()-.5)*500,(rnd()-.5)*190,-60-rnd()*360],r=3+rnd()*9;if(positions.some(p=>V3.len(V3.sub(pos,p))<r+18)||V3.len(pos)<45)continue;this.asteroids.push({pos,r,phase:rnd()*6.28,variant:i%3})}this.station={pos:[115,25,-210],r:16};this.portal={pos:[0,0,-330],r:11};this.pickups.push({type:'repair',pos:[-26,2,-100],r:5,dead:false},{type:'missiles',pos:[38,-5,-220],r:5,dead:false})}
 start(assist=false){this.assist=assist;this.beginStage(0)}
 beginStage(n){this.stage=n;this.status='playing';this.stageKills=0;this.stageTime=0;this.spawnClock=2.7;this.boss=null;this.bossDefeated=false;this.enemies=[];this.bullets=[];this.hostile=[];this.particles=[];this.trails=[];this.flash=0;this.shake=0;this.lock=null;this.comboTime=0;this.combo=0;Object.assign(this.player,{pos:[0,0,0],yaw:0,pitch:0,bank:0,hp:Math.min(100,this.player.hp+(n?35:0)),energy:100,speed:20,invulnerable:3,shotCooldown:0,missileCooldown:0,missiles:Math.max(6,this.player.missiles),pulseCooldown:0,flipCooldown:0,boosting:false});this.setupWorld(n);this.emit('stage',n)}
 pause(){if(this.status==='playing'){this.status='paused';this.emit('state','paused')}}
 resume(){if(this.status==='paused'){this.status='playing';this.emit('state','playing')}}
 next(){if(this.status==='stageclear'&&this.stage<3)this.beginStage(this.stage+1)}
 target(){const p=this.player,b=flightBasis(p.yaw,p.pitch),all=[...this.enemies,...(this.boss?[this.boss]:[])];let best=null,score=-1;for(const e of all){if(e.dead)continue;const delta=V3.sub(e.pos,p.pos),distance=V3.len(delta),align=V3.dot(b.f,V3.norm(delta));if(distance<230&&align>.90){const v=align-distance*.00008;if(v>score){best=e;score=v}}}return best}
 burst(pos,color,count=20){for(let i=0;i<count;i++){const v=V3.norm([this.random()-.5,this.random()-.5,this.random()-.5]),life=.3+this.random()*.65;this.particles.push({pos:pos.slice(),vel:V3.scale(v,8+this.random()*24),life,max:life,color,size:.2+this.random()*.8})}if(this.particles.length>180)this.particles.splice(0,this.particles.length-180)}
 spawnEnemy(){if(this.enemies.length>=6)return;const p=this.player,b=flightBasis(p.yaw,p.pitch),theta=(this.random()-.5)*1.3,distance=90+this.random()*50,dir=V3.norm(V3.add(b.f,V3.add(V3.scale(b.r,theta),V3.scale(b.u,(this.random()-.5)*.45)))),type=this.stage>1&&this.random()<.25?'heavy':this.random()<.38?'hunter':'scout',info=FLIGHT_ENEMIES[type];let pos=V3.add(p.pos,V3.scale(dir,distance));for(const a of this.asteroids)if(V3.len(V3.sub(a.pos,pos))<a.r+8)pos[1]+=a.r+15;this.enemies.push({...info,type,id:++this.entityId,pos,vel:V3.scale(dir,-info.speed),age:0,shot:1.8+this.random(),hit:0,phase:this.random()*6.28,dead:false})}
 fire(){const p=this.player;if(this.status!=='playing'||p.shotCooldown>0)return false;const b=flightBasis(p.yaw,p.pitch,p.bank);p.shotCooldown=.13;this.shots++;const target=this.target(),aim=target&&V3.dot(V3.norm(V3.sub(target.pos,p.pos)),b.f)>.975?V3.norm(V3.sub(V3.add(target.pos,V3.scale(target.vel||[0,0,0],V3.len(V3.sub(target.pos,p.pos))/210)),p.pos)):b.f;for(const side of [-1,1])this.bullets.push({pos:V3.add(p.pos,V3.add(V3.scale(b.r,side*1.7),V3.scale(b.f,3))),vel:V3.scale(aim,210),life:1.7,damage:13,r:.4,type:'laser',color:'#82f8ff'});this.emit('shot');return true}
 missile(){const p=this.player;if(this.status!=='playing'||p.missileCooldown>0||p.missiles<1)return false;const target=this.target();if(!target){this.emit('notice','Наведите прицел на противника: ракете нужен захват.');return false}p.missiles--;p.missileCooldown=1.0;const b=flightBasis(p.yaw,p.pitch);this.bullets.push({pos:V3.add(p.pos,V3.scale(b.f,4)),vel:V3.scale(b.f,85),life:5,damage:100,r:.8,type:'missile',target:target.id,color:'#ffd28c'});this.emit('missile');return true}
 pulse(){const p=this.player;if(this.status!=='playing'||p.pulseCooldown>0)return false;p.pulseCooldown=14;p.invulnerable=Math.max(p.invulnerable,1);this.pulseWave=1;this.hostile=this.hostile.filter(b=>V3.len(V3.sub(b.pos,p.pos))>75);for(const e of [...this.enemies,...(this.boss?[this.boss]:[])])if(V3.len(V3.sub(e.pos,p.pos))<75)this.hit(e,75);this.emit('pulse');return true}
 flip(){if(this.status!=='playing'||this.player.flipCooldown>0)return false;this.player.yaw+=Math.PI;this.player.pitch=-this.player.pitch;this.player.flipCooldown=4;this.player.invulnerable=Math.max(.5,this.player.invulnerable);this.emit('flip');return true}
 damage(amount){const p=this.player;if(this.status!=='playing'||p.invulnerable>0)return false;p.hp=Math.max(0,p.hp-amount*(this.assist?.55:1));p.invulnerable=.65;this.flash=.28;this.shake=.35;this.combo=0;this.comboTime=0;this.emit('damage');if(p.hp<=0){this.burst(p.pos,'#ff9c69',70);this.status='lost';this.emit('state','lost')}return true}
 hit(e,amount){if(e.dead)return;e.hp-=amount;e.hit=.12;this.hitFlash=.12;this.hits++;if(e.hp<=0){e.dead=true;this.totalKills++;this.stageKills+=e.type==='boss'?0:1;this.combo++;this.comboTime=5;this.maxCombo=Math.max(this.maxCombo,this.combo);this.score+=Math.round((e.points||2000)*(1+Math.min(12,this.combo-1)*.1));this.burst(e.pos,e.color,e.type==='boss'?75:28);if(e.type==='boss'){this.boss=null;this.bossDefeated=true;this.hostile=[];this.emit('boss-defeated')}else{if(this.totalKills%3===0)this.pickups.push({type:this.totalKills%6===0?'missiles':'repair',pos:e.pos.slice(),r:6,dead:false});this.emit('destroy',e.type)}}}
 collect(item){if(item.dead||this.status!=='playing')return;item.dead=true;if(item.type==='requirement'){if(this.rescued.includes(item.reqId))return;this.rescued.push(item.reqId);this.lastRescued=item.reqId;this.score+=350;this.player.hp=Math.min(100,this.player.hp+10);this.burst(item.pos,'#72ffd8',22);this.emit('rescue',item.reqId)}else if(item.type==='repair'){this.player.hp=Math.min(100,this.player.hp+30);this.emit('pickup','Щит восстановлен +30')}else{this.player.missiles=Math.min(12,this.player.missiles+3);this.emit('pickup','Ракеты +3')}}
 hostileShot(e,spread=0){const lead=V3.add(this.player.pos,V3.scale(flightBasis(this.player.yaw,this.player.pitch).f,this.player.speed*.35)),d=V3.norm(V3.add(V3.sub(lead,e.pos),[spread,0,0]));this.hostile.push({pos:e.pos.slice(),vel:V3.scale(d,this.assist?40:53),life:5,r:1.1,damage:e.type==='boss'?18:12,color:e.type==='boss'?'#db90ff':'#ff886f'})}
 enemyStep(dt){const p=this.player;for(const e of this.enemies){if(e.dead)continue;e.age+=dt;e.hit=Math.max(0,e.hit-dt);const d=V3.sub(p.pos,e.pos),dist=V3.len(d),toward=V3.norm(d),tangent=V3.norm(V3.cross(toward,[0,1,0]));let want=V3.add(V3.scale(toward,dist>55?1:dist<32?-1:0),V3.scale(tangent,.9*Math.sin(e.phase+e.age*.2)));want=V3.add(want,[0,Math.sin(e.age*.8+e.phase)*.2,0]);for(const a of this.asteroids){const away=V3.sub(e.pos,a.pos),ad=V3.len(away);if(ad<a.r+14)want=V3.add(want,V3.scale(V3.norm(away),2*(1-ad/(a.r+14))))}e.vel=V3.lerp(e.vel,V3.scale(V3.norm(want),e.speed),1-Math.exp(-dt*2));e.pos=V3.add(e.pos,V3.scale(e.vel,dt));e.shot-=dt;if(e.shot<=0&&dist<160){e.shot=(this.assist?3.2:2.3)+(e.type==='heavy'?.2:.6);this.hostileShot(e)}if(dist<e.r+2){this.damage(18);e.pos=V3.add(e.pos,V3.scale(toward,-8))}if(dist>350)e.dead=true}
 if(this.boss){const b=this.boss;b.age+=dt;b.hit=Math.max(0,b.hit-dt);const d=V3.sub(p.pos,b.pos),dist=V3.len(d);b.vel=V3.scale(V3.norm(d),dist>105?10:dist<65?-8:0);b.pos=V3.add(b.pos,V3.scale(b.vel,dt));b.shot-=dt;if(b.shot<=0){b.shot=b.hp<b.maxHp*.5?1.1:1.9;for(const s of [-12,0,12])this.hostileShot(b,s)}if(dist<b.r+2)this.damage(30)}}
 checkStage(){if(this.status!=='playing')return;const all=this.plan[this.stage].every(id=>this.rescued.includes(id)),quota=ARCADE_SECTORS[this.stage].quota;if(this.stage===3&&this.stageKills>=quota&&!this.boss&&!this.bossDefeated){const p=this.player,b=flightBasis(p.yaw,p.pitch),hp=this.assist?650:950;this.boss={id:++this.entityId,type:'boss',pos:V3.add(p.pos,V3.scale(b.f,140)),vel:[0,0,0],hp,maxHp:hp,r:15,age:0,shot:3,hit:0,color:'#da99ff',points:3000};this.hostile=[];this.emit('boss')}
 if(all&&this.stageKills>=quota&&(this.stage<3||this.bossDefeated)){this.status=this.stage===3?'won':'stageclear';this.score+=Math.round(this.player.hp*10);this.emit('state',this.status)}}
 step(delta,input={}){if(this.status!=='playing')return;const dt=arcadeClamp(Number.isFinite(delta)?delta:0,0,.04),p=this.player;this.elapsed+=dt;this.stageTime+=dt;this.flash=Math.max(0,this.flash-dt);this.shake=Math.max(0,this.shake-dt);this.hitFlash=Math.max(0,this.hitFlash-dt);this.pulseWave=Math.max(0,this.pulseWave-dt);this.comboTime=Math.max(0,this.comboTime-dt);if(!this.comboTime)this.combo=0;for(const k of ['shotCooldown','missileCooldown','invulnerable','pulseCooldown','flipCooldown'])p[k]=Math.max(0,p[k]-dt);
 const tx=arcadeClamp(input.turn||0,-1,1),ty=arcadeClamp(input.pitch||0,-1,1);p.yaw+=tx*1.28*dt;p.pitch=arcadeClamp(p.pitch+ty*1.05*dt,-1.43,1.43);p.bank+=(-tx*.64-p.bank)*Math.min(1,dt*5);p.boosting=!!input.boost&&p.energy>1;if(p.boosting)p.energy=Math.max(0,p.energy-dt*23);else p.energy=Math.min(100,p.energy+dt*15);const cruise=Number.isFinite(input.cruiseSpeed)?arcadeClamp(input.cruiseSpeed,0,58):input.brake?6:p.boosting?58:22;p.speed+=(cruise-p.speed)*Math.min(1,dt*4);const basis=flightBasis(p.yaw,p.pitch),old=p.pos.slice();p.pos=V3.add(p.pos,V3.scale(basis.f,p.speed*dt));if(this.resolveFlightMovement)this.resolveFlightMovement(old,p,dt);if(this.status!=='playing')return;
 if(input.flip)this.flip();if(input.pulse)this.pulse();this.lock=this.target()?.id||null;if(input.fire)this.fire();if(input.missile)this.missile();
 this.spawnClock-=dt;if(this.spawnClock<=0){this.spawnClock=this.assist?3.8:Math.max(2,3.8-this.stage*.45);if(this.stageKills<ARCADE_SECTORS[this.stage].quota||this.stage===3&&!this.bossDefeated)this.spawnEnemy()}this.enemyStep(dt);
 for(const bullet of this.bullets){if(bullet.type==='missile'){const t=[...this.enemies,...(this.boss?[this.boss]:[])].find(e=>e.id===bullet.target&&!e.dead);if(t)bullet.vel=V3.scale(V3.norm(V3.lerp(V3.norm(bullet.vel),V3.norm(V3.sub(t.pos,bullet.pos)),Math.min(1,dt*4))),100)}const prev=bullet.pos;bullet.pos=V3.add(prev,V3.scale(bullet.vel,dt));bullet.life-=dt;if(this.blockFlightShot?.(prev,bullet.pos,bullet,false)){bullet.life=0;continue}let hit=null,tmin=2;for(const e of [...this.enemies,...(this.boss?[this.boss]:[]),...this.asteroids.map(a=>({...a,asteroid:true}))]){if(e.dead)continue;const t=flightSegment(prev,bullet.pos,e.pos,e.r+bullet.r);if(t!==null&&t<tmin){tmin=t;hit=e}}if(hit){bullet.life=0;if(hit.asteroid)this.burst(bullet.pos,'#b1b7c9',4);else this.hit(hit,bullet.damage)}}
 for(const bullet of this.hostile){const prev=bullet.pos;bullet.pos=V3.add(prev,V3.scale(bullet.vel,dt));bullet.life-=dt;if(this.blockFlightShot?.(prev,bullet.pos,bullet,true)){bullet.life=0;continue}if(flightSegment(prev,bullet.pos,p.pos,2.1+bullet.r)!==null){bullet.life=0;this.damage(bullet.damage)}else for(const a of this.asteroids)if(flightSegment(prev,bullet.pos,a.pos,a.r)!==null){bullet.life=0;break}}
 for(const a of this.asteroids)if(flightSegment(old,p.pos,a.pos,a.r+1.6)!==null){this.damage(20);p.pos=V3.add(a.pos,V3.scale(V3.norm(V3.sub(old,a.pos)),a.r+3));p.speed=6;break}
 for(const item of this.pickups)if(!item.dead&&flightSegment(old,p.pos,item.pos,item.r+2)!==null)this.collect(item);
 const baseDist=V3.len(p.pos);this.warning=baseDist>600?'Далеко от задания · R — разворот':'';if(baseDist>900){p.yaw=Math.atan2(-p.pos[0],p.pos[2]);p.pitch=Math.atan2(-p.pos[1],Math.hypot(p.pos[0],p.pos[2]));this.emit('notice','Навигация: курс возвращён к Цитадели.');}
 this.trails.push({pos:p.pos.slice(),life:.8,boost:p.boosting});if(this.trails.length>48)this.trails.shift();for(const t of this.trails)t.life-=dt;for(const q of this.particles){q.pos=V3.add(q.pos,V3.scale(q.vel,dt));q.life-=dt}this.enemies=this.enemies.filter(e=>!e.dead);this.bullets=this.bullets.filter(b=>b.life>0);this.hostile=this.hostile.filter(b=>b.life>0);this.particles=this.particles.filter(q=>q.life>0);this.trails=this.trails.filter(t=>t.life>0);this.checkStage();}
}

