 interact(){if(this.status==='playing'&&this.phase==='dock'){if(V3.len(V3.sub(this.player.pos,this.dockPoint()))<33){this.status='docking';this.phaseClock=0;this.autopilot=false;this.say('Стыковка разрешена. Высаживаемся в '+CITADEL_MISSIONS[this.stage].landing+'.','order',true);this.emit('state','docking');return true}this.say('Подойди к голубому шлюзу. G проложит курс. В зоне стыковки нажми F.','order',true);return false}if(this.status==='boarding')return this.boardInteract();return false}
 checkStage(){if(this.status!=='playing')return;if(this.stationHp<=0||this.nodes.every(n=>n.integrity<=0)){this.lossReason=this.stationHp<=0?'Редакцию замотали изменениями. Перехватывайте существенные замечания и защищайте готовность к принятию.':'Все узлы заблокированы замечаниями. Сначала перехватывайте критические замечания у лучей.';this.status='lost';this.emit('state','lost');return}if(this.phase==='battle'&&this.waveSpawned>=this.waveTotal()&&!this.enemies.some(e=>!e.dead)){if(this.wave<3){if(!this.waveClock){this.waveClock=2.5;this.say('Волна отбита. Следующая через три секунды.','success',true)}}else if(this.stage===3&&!this.bossDefeated){if(!this.boss){const hp=this.assist?1000:1450;this.boss={id:++this.entityId,type:'boss',name:'Бесконечное согласование',pos:V3.add(this.station.pos,[-30,25,-160]),vel:[0,0,0],hp,maxHp:hp,r:15,age:0,shot:3,hit:0,color:'#da99ff',points:4000};this.hostile=[];this.say('Крейсер вышел на орбиту! Ракеты Q, импульс E на сближении. Держи дистанцию.','danger',true);this.emit('boss')}}else this.beginRetrieval()}if(this.phase==='retrieve'&&this.modules().every(n=>n.dead)&&!this.lessonQueue.length){this.phase='dock';this.navMode='objective';this.autopilot=true;this.say('Все модули у нас. Автокурс ведёт к Цитадели. На сближении начнётся стыковка; вручную — F.','success',true);this.emit('phase','dock')}}
 beginRetrieval(){this.phase='retrieve';this.hostile=[];this.navMode='objective';this.autopilot=true;this.notify('ОРБИТА ЗАЧИЩЕНА','Соберите оставшиеся модули · автокурс включён');this.say('Орбита чиста. Автокурс ведёт к ближайшему кристаллу. Он соберётся сам на расстоянии 30 м.','success',true);this.emit('phase','retrieve')}

 beginBoarding(){this.status='boarding';this.phase='boarding';this.autopilot=false;this.player.hp=Math.max(80,this.player.hp);this.board={pos:[0,0,11],yaw:Math.PI,hp:100,cooldown:0,invulnerable:1,time:0,kills:0,enemies:[],bullets:[],hostile:[],terminal:0,completed:[],question:null,answered:false,returning:false,guide:false,crates:[{x:-6,z:1,w:2,h:3},{x:6,z:1,w:2,h:3},{x:-5,z:-10,w:2.5,h:2},{x:5,z:-10,w:2.5,h:2}],terminals:[[-13,0,-9],[13,0,-9],[0,0,-19]]};this.spawnBoardWave(5+this.stage);this.say('Высадка выполнена. WASD — движение, пробел — перехват замечаний. Затем подойди к терминалу и выбери решение: F.','order',true);this.emit('state','boarding')}
