 answer(index){const b=this.board;if(this.status!=='remark'||b.answered||!Number.isInteger(index)||index<0||index>2)return false;const q=citadelRemarkCase(this,b.question),correct=index===q.correct;b.answered=true;this.remarkFeedback={correct,index,why:q.why};if(correct){b.completed.push(b.question);this.completedRemarks.push(b.question);this.score+=500;citadelOutcomeNotice(this,q)}else{this.score=Math.max(0,this.score-100);this.say('Это решение не сохраняет целостность ФТ. Разбери пояснение и попробуй ещё раз.','alert',true)}this.emit('answer',correct);return correct}
