function citadelVariantIndex(e,slot){return ((Math.abs(Number(e.seed)||0)>>>0)+Math.imul(slot+7,2654435761)>>>0)%3}
function citadelLessonCase(e,index){const base=CITADEL_LESSONS[index],n=e.caseBank===0?0:citadelVariantIndex(e,index),meta=citadelCaseMetadata('lesson',index,n);if(!n)return {...base,...meta};const v=CITADEL_LESSON_VARIANTS[index][n-1];return {...base,skill:v[0],situation:v[1],why:v[2],takeaway:meta.outcome.title,followup:v[3]||'',...meta}}
function citadelRemarkCase(e,index){const base=CITADEL_REMARKS[index],n=e.caseBank===0?0:citadelVariantIndex(e,index+8),meta=citadelCaseMetadata('remark',index,n);if(!n)return {...base,...meta};const v=CITADEL_REMARK_VARIANTS[index][n-1];return {...base,q:v[0],choices:v[1],why:v[2],followup:'',...meta}}

