function citadelCaseMetadata(kind,index,variant=0){
 const row=(kind==='lesson'?LESSON_OUTCOMES:kind==='remark'?REMARK_OUTCOMES:FINALE_OUTCOMES)[index],v=kind==='final'?row:row[variant];
 const [origin,severity,resolution,before,after,title]=v;
 return {origin,severity:{К:'Критическое',С:'Существенное',Р:'Редакционное'}[severity],caseId:(kind==='lesson'?'L':kind==='remark'?'T':'F')+String(index+1).padStart(2,'0')+'.'+variant,sourceKind:'synthetic',resolution,outcome:{...CITADEL_RESOLUTIONS[resolution],before,after,title}};
}
function citadelFinalCase(index){return {...FINALE_TRIALS[index],...citadelCaseMetadata('final',index)}}
function citadelResolvedCases(e){
 const rows=[...e.decisions.map(x=>({...citadelLessonCase(e,x.caseIndex),stage:x.stage})),...e.completedRemarks.map(i=>({...citadelRemarkCase(e,i),stage:Math.floor(i/3)}))];
 for(const i of e.finale?.tests||[])rows.push({...citadelFinalCase(i),stage:4});
 return rows.sort((a,b)=>a.stage-b.stage||a.caseId.localeCompare(b.caseId));
}
function citadelOutcomeNotice(e,q){e.notify(q.outcome.title,q.outcome.after);e.say(q.outcome.title+'. '+q.outcome.after,'success',true)}

