 boardInteract(){if(this.finale?.phase!=='maze')return this.finale?false:super.boardInteract();const b=this.board;if(b.completed.length===3){if(V3.len(V3.sub(b.pos,b.exit))<3.2)this.beginMRG();return true}const point=b.terminals[b.completed.length];if(V3.len(V3.sub(b.pos,point))<2.9&&stationLine(b,b.pos,point,.15)){this.status='finalcheck';this.finale.answer=null;this.emit('terminal');this.emit('state','finalcheck');return true}return false}
 answerFinale(index){if(this.status!=='finalcheck'||this.finale.answer!==null||!Number.isInteger(index)||index<0||index>2)return false;const q=FINALE_TRIALS[this.board.completed.length];this.finale.answer=index;const ok=index===q.correct;this.emit('answer',ok);return ok}
