 add('box',[0,1.7,-23],[18,2,1],'#344a63');for(const side of [-1,1]){add('box',[side*18,1.5,-5],[1,1.8,18],'#344a63');for(let z=-20;z<=12;z+=6){add('box',[side*16.9,2,z],[.06,.8,.6],'#67bbd9',.8);add('box',[side*17,1.5,z],[.4,1.8,.25],'#697c8f')}}add('box',[0,3,-22.9],[9,.08,.08],accent,1);for(const side of [-1,1]){for(let i=0;i<4;i++){const x=side*(5+i*2.3);add('box',[x,1.4,-21],[.75,1.8,.7],'#243e53');for(let k=0;k<5;k++)add('box',[x,.1+k*.6,-20.27],[.5,.045,.025],accent,.7)}for(let z=-17;z<10;z+=3)add('box',[side*15.8,.015,z],[.05,.015,.7],accent,.5)}add('octa',[0,4.4+Math.sin(time)*.15,-20],[1.3,1.8,1.3],accent,.75,flightBasis(time*.5,.2),.65);add('ring',[0,4.4,-20],[2.1,2.1,2.1],accent,.7,flightBasis(.1,time*.3),.45);
 for(const crate of b.crates){add('armor',[crate.x,1,crate.z],[crate.w,1,crate.h],'#496277');add('box',[crate.x,2.05,crate.z],[crate.w*.9,.08,crate.h*.9],'#8195a0');for(const side of [-1,1])add('box',[crate.x+side*crate.w*.7,2.15,crate.z],[.05,.03,crate.h*.7],'#ecc584',.5)}
 for(let i=0;i<3;i++){const p=b.terminals[i],done=b.completed.length>i,active=b.completed.length===i,col=done?'#6be3b1':active?'#ffc57d':'#62748d';add('box',V3.add(p,[0,1,0]),[1.65,1,1],'#3e536c');add('box',V3.add(p,[0,2.1,-.15]),[1.5,.1,.8],col,.8,flightBasis(0,.3));add('box',V3.add(p,[0,3,-.8]),[1.4,.8,.08],col,.7);if(active)add('ring',V3.add(p,[0,.03,0]),[3,3,3],col,1,flightBasis(0,Math.PI/2),.7)}
 add('box',[0,.02,11],[3,.03,2],'#2b776e',.5);add('ring',[0,.1,11],[3,3,3],'#71f2c8',1,flightBasis(0,Math.PI/2),.65);
