function finalePersist(e){if(!e.finale)return;e.finale.checkpointScore=e.score;const save={schema:'citadel-finale-v1',caseBank:e.caseBank??1,checkpoint:e.finale.checkpoint,seed:e.seed,assist:e.assist,score:e.score,totalKills:e.totalKills,elapsed:e.elapsed,rescued:e.rescued.slice(),completedRemarks:e.completedRemarks.slice(),decisions:e.decisions.map(x=>({...x})),upgrades:{...e.upgrades},escorts:(e.escorts||[]).map(x=>({...x}))};try{localStorage.setItem(FINALE_SAVE_KEY,JSON.stringify(save));ARCADE.finaleCheckpoint=save}catch{ARCADE.storage=false;ARCADE.finaleCheckpoint=save}}
function finaleReadSave(){try{const s=ARCADE.finaleCheckpoint||JSON.parse(localStorage.getItem(FINALE_SAVE_KEY)||'null');if(!s||s.schema!=='citadel-finale-v1'||!['boss','breach','maze','mrg','upload','victory'].includes(s.checkpoint)||!Number.isInteger(s.seed)||s.seed<0||s.seed>4294967295||typeof s.assist!=='boolean'||!Number.isFinite(s.elapsed)||s.elapsed<0||s.elapsed>1e8||!Number.isInteger(s.score)||s.score<0||s.score>1e9||!Number.isInteger(s.totalKills)||s.totalKills<0||s.totalKills>1e6)return null;const plan=arcadePlan(s.seed).flat();if(!Array.isArray(s.rescued)||s.rescued.length!==12||new Set(s.rescued).size!==12||!s.rescued.every(x=>plan.includes(x))||!Array.isArray(s.completedRemarks)||s.completedRemarks.length!==12||new Set(s.completedRemarks).size!==12||!s.completedRemarks.every(x=>Number.isInteger(x)&&x>=0&&x<12)||!Array.isArray(s.decisions)||s.decisions.length!==8||new Set(s.decisions.map(x=>x.caseIndex)).size!==8||!s.decisions.every(x=>x&&Number.isInteger(x.caseIndex)&&x.caseIndex>=0&&x.caseIndex<8&&x.stage===Math.floor(x.caseIndex/2)&&x.reqId===arcadePlan(s.seed)[x.stage][x.caseIndex%2?2:0]&&x.decision===CITADEL_LESSONS[x.caseIndex].correct&&typeof x.firstTry==='boolean')||!s.upgrades||!Object.keys(CITADEL_UPGRADES).every(k=>Number.isInteger(s.upgrades[k])&&s.upgrades[k]>=0&&s.upgrades[k]<=3))return null;if(!Array.isArray(s.escorts)||s.escorts.length>3)return null;return s}catch{return null}}
