function drawFinaleRadar(c,e){const w=c.canvas.width,h=c.canvas.height;c.fillStyle='#061421';c.fillRect(0,0,w,h);c.fillStyle='#385165';c.fillRect(15,h-30,w-30,4);const b=e.board,m=e.finale.mrg,x=15+(b.pos[0]+35)/70*(w-30);c.fillStyle='#a7f6df';c.fillRect(x-3,h-30-b.pos[1]*5,6,10);c.fillStyle=e.finale.open?'#ffe0a2':'#b695d6';c.beginPath();c.arc(w-40,h-80,19,0,Math.PI*2);c.fill();c.font='bold 13px Arial';c.textAlign='center';c.fillStyle='#d4e7e5';c.fillText('МРГ · '+Math.ceil(m.hp/m.maxHp*100)+'%',w/2,28)}

