/* Tournament integration v1.1.0. In-game records and name-only device entry; no owner test shortcuts. */
const CUP_API='https://cmpon-metrics-service.carlafloriano1958.chatgpt.site/api/tournament/';
const CUP={config:null,player:null,token:'',runs:[],run:null,clock:0,startClock:0,startScore:0,progress:0,queue:[],sending:false,conflict:false,saveText:'',board:-1,selected:'',mode:'calm',rows:null,error:'',ready:false,lastSave:0,attached:false,panel:null,panelState:null,panelFocus:null,uiRevision:0,boardSerial:0,boardError:'',busy:false,nameDraft:'',renameDraft:null,deviceKey:'',verified:false,recovered:false,authPromise:null,refreshPromise:null,flushPromise:null};
const CUP_LEVELS=['Орбита ФЗ','Архив ФЗ','Коридор исполнения','Орбита исполнителя','Машинный зал','Переход интеграций','Орбита смежников','Палуба интеграций','Последняя миля','Итоговая орбита','Палуба менеджмента','Параллакс','Лабиринт логова','Главный компьютер МРГ'];
const CUP_ENGINE_KEYS='seed plan status stage assist score rescued lastRescued elapsed totalKills shots hits combo maxCombo comboTime player stageKills stageTime enemies bullets hostile pickups particles trails boss bossDefeated entityId flash shake hitFlash spawnClock pulseWave lock warning asteroids station portal phase wave waveSpawned waveClock phaseClock stationHp nodes upgrades upgradeChoice selectedTarget autopilot captain captainClock lossReason explosions board remarkFeedback lastDamage completedRemarks decisions lessonQueue lesson navMode toast firstActionTime resumeStatus escorts escort crash speechUntil finale navWatch missileFlash caseBank dock stageStart waveSpawnTimer idleHintClock location'.split(' ');
const CUP_OMIT=new Set(['hullCache','detour','nav','navExtras','pathCache','guideRoute','guideWatch']);
function cupPack(e){const engine={};for(const k of CUP_ENGINE_KEYS)if(e[k]!==undefined)engine[k]=e[k];return JSON.parse(JSON.stringify({schema:1,engine,rng:e.random.getState(),meta:{clock:CUP.clock,startClock:CUP.startClock,startScore:CUP.startScore,progress:CUP.progress}},(k,v)=>CUP_OMIT.has(k)?undefined:v instanceof Set?{_cupSet:[...v]}:v instanceof Map?{_cupMap:[...v]}:v));}
function cupUnpack(snapshot,run,emit=arcadeEvent){if(snapshot?.schema!==1||snapshot.engine.seed!==run.seed||snapshot.engine.assist!==(run.mode==='calm'))throw Error('Сохранение несовместимо с попыткой.');const saved=JSON.parse(JSON.stringify(snapshot),(_,v)=>v&&Array.isArray(v._cupSet)?new Set(v._cupSet):v&&Array.isArray(v._cupMap)?new Map(v._cupMap):v);const e=new RequirementArcade(run.seed);e.start(run.mode==='calm');for(const k of CUP_ENGINE_KEYS)if(Object.hasOwn(saved.engine,k))e[k]=saved.engine[k];e.random=arcadeSeed(snapshot.rng);e.hullCache=null;e.detour=null;if(e.board?.cells)stationBuildNav(e.board);e.emit=emit;return e;}
function cupPersist(){try{localStorage.setItem('cmpon.cup.session.v1',JSON.stringify({token:CUP.token,player:CUP.player}));if(CUP.run)localStorage.setItem('cmpon.cup.outbox.v1',JSON.stringify({playerId:CUP.player?.id,run:CUP.run,queue:CUP.queue,progress:CUP.progress,clock:CUP.clock,startClock:CUP.startClock,startScore:CUP.startScore}));}catch{CUP.saveText='Память браузера заполнена — не закрывайте игру до синхронизации.';}}
async function cupAPI(path,body){const r=await fetch(CUP_API+path,{method:body?'POST':'GET',mode:'cors',credentials:'omit',headers:{...(body?{'Content-Type':'application/json'}:{}),...(CUP.token?{Authorization:'Bearer '+CUP.token}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});let data;try{data=await r.json();}catch{throw Error('Не удалось прочитать ответ сервера.');}if(!r.ok){const err=Error(data.error||'Не удалось выполнить запрос.');err.status=r.status;throw err;}return data;}
function cupStatus(t){CUP.saveText=t;const el=document.getElementById('cup-save-status');if(el)el.textContent=t;const bar=document.getElementById('arcade-renderer');if(bar&&CUP.attached){bar.textContent=t;bar.title=t;}}
function cupEnqueue(result){if(CUP.progress===14&&!result)return;if(!CUP.attached||!CUP.run||CUP.conflict||!ARCADE.engine||CUP.run.status==='complete')return;const job={id:CUP.run.id,requestId:crypto.randomUUID(),clock:Math.round(CUP.clock),snapshot:cupPack(ARCADE.engine),...(result?{result}:{})};const last=CUP.queue.at(-1);if(!result&&last&&!last.result&&!last.revisionAssigned)CUP.queue[CUP.queue.length-1]=job;else CUP.queue.push(job);cupPersist();cupStatus('Сохраняем…');void cupFlush();}
function cupFlush(){
 if(CUP.flushPromise)return CUP.flushPromise;
 if(CUP.conflict||!CUP.run||!CUP.queue.length)return Promise.resolve();
 CUP.sending=true;
 CUP.flushPromise=(async()=>{try{
  while(CUP.queue.length){
   const job=CUP.queue[0];if(!job.revisionAssigned){job.revision=CUP.run.revision;job.revisionAssigned=true;cupPersist();}
   const {revisionAssigned,...body}=job;let data;
   try{data=await cupAPI('save',body);}catch(e){if(e.status!==401)throw e;CUP.verified=false;await cupEnsureProfile();data=await cupAPI('save',body);}
   CUP.run={...CUP.run,...data.run};CUP.queue.shift();cupPersist();
  }
  cupStatus(CUP.run.status==='complete'?'Победа сохранена · результат в рекордах':'Сохранено · '+CUP.progress+'/14 этапов');
 }catch(e){
  if([400,409,413].includes(e.status)){CUP.conflict=true;ARCADE.engine?.pause();cupStatus(e.message+' Вернитесь в меню игры и продолжите из облака.');}
  else if(e.status===401){ARCADE.engine?.pause();cupStatus('Не удалось восстановить вход. Сохранение осталось в этом браузере.');}
  else cupStatus('Нет связи · сохранено на устройстве, повторим отправку.');
 }finally{CUP.sending=false;}})();
 return CUP.flushPromise.finally(()=>{CUP.flushPromise=null;});
}
function cupComplete(level,e){if(e!==ARCADE.engine||!CUP.attached||!CUP.run||CUP.progress!==level||CUP.conflict)return;const clock=Math.round(CUP.clock),result={level,score:Math.max(0,Math.round(e.score-CUP.startScore)),campaignScore:Math.round(e.score),duration:Math.max(0,clock-Math.round(CUP.startClock)),clock};CUP.progress++;CUP.startClock=CUP.clock;CUP.startScore=e.score;cupEnqueue(result);}
