cupHook('beginBreach',()=>11,e=>e.finale?.phase==='breach');
cupHook('beginMRG',()=>12,e=>e.finale?.phase==='mrg');
cupHook('beginUpload',()=>13,(e,r)=>r===true&&e.finale?.phase==='upload');
function cupTick(dt){if(!CUP.panel&&CUP.attached&&CUP.run&&!CUP.conflict&&!document.hidden&&['playing','boarding','docking','lesson','remark','finalcheck','crashing'].includes(ARCADE.engine?.status))CUP.clock+=dt*1000;}
const cupOriginalFrame=arcadeFrame;arcadeFrame=function(now){if(ARCADE.canvas&&STATE.view==='arcade')cupTick(Math.min(.04,Math.max(0,(now-ARCADE.lastTime)/1000)));cupOriginalFrame(now);};
