function cupPlayableRun(){const id=CUP.config?.cups.find(c=>c.state==='active')?.id||null;return [CUP.run,...CUP.runs].find(r=>r&&r.cupId===id&&r.status==='active'&&r.progress<14&&r.gameVersion===CUP_GAME_VERSION)||null;}
function cupLobbyHTML(){
 const c=cupCurrent(),r=cupPlayableRun(),active=c?.state==='active';
 return `<div class="arcade-menu campaign-menu cup-lobby"><div class="cup-lobby-heading"><span class="arcade-serial">РЕДАКЦИЯ ПОД ЗАЩИТОЙ</span><h3>ЦИТАДЕЛЬ <span>ЦСИИ</span></h3><p>Защитите ФТ от лишних замечаний и доведите документ до согласования.</p></div>
 <div class="cup-notice" id="cup-notice" role="status">${cupNotice()}</div>
 <div class="cup-entry">${CUP.player?`<div class="cup-identity"><span>Аналитик <b>${esc(CUP.player.name)}</b></span><button class="cup-link" data-action="cup-rename">Изменить имя</button></div><button class="arcade-play" data-action="cup-play"${CUP.busy?' disabled':''}>${CUP.busy?'Подключаем…':r?(CUP.conflict?'Продолжить из облака':'Продолжить игру')+' · '+r.progress+'/14': 'Начать игру →'}</button>${r?'<button class="cup-link" data-action="cup-new">Начать заново</button>':''}`:`<form id="cup-entry-form"><label for="cup-name">Как вас записать в таблице?</label><div class="cup-name-row"><input id="cup-name" name="name" autocomplete="nickname" enterkeyhint="go" minlength="2" maxlength="32" required placeholder="Имя или позывной" value="${attr(CUP.nameDraft||'')}" aria-describedby="cup-entry-hint"><button class="arcade-play" type="submit"${CUP.busy?' disabled':''}>${CUP.busy?'Подключаем…':'Начать игру →'}</button></div></form>`}
 <small id="cup-entry-hint">${active?'Участвуете автоматически. ':''}Имя и прогресс запомнятся в этом браузере.</small>
 ${active?'<small class="cup-mode-hint">Для всех участников включён '+(c.mode==='calm'?'учебный':'боевой')+' режим.</small>':`<div class="arcade-mode"><button data-action="arcade-mode" data-value="calm" class="${ARCADE.mode==='calm'?'active':''}">Учебный</button><button data-action="arcade-mode" data-value="normal" class="${ARCADE.mode==='normal'?'active':''}">Боевой</button></div>`}
 <p id="cup-message" class="cup-message" role="status">${esc(CUP.error)}</p></div>
 <div class="cup-lobby-footer"><button class="arcade-secondary" data-action="cup-records">Рекорды</button>${CUP.error?'<button class="cup-link" data-action="cup-refresh">Повторить подключение</button><button class="cup-link" data-action="cup-guest">Пока без рейтинга</button>':'<small>4 редакции · 14 этапов · финал с МРГ</small>'}</div>
 <small class="app-release">Приложение v${esc(APP_RELEASE.version)} · ФТ 2.0.2</small></div>`;
}
function cupBoardHTML(){
 if(CUP.boardError)return `<p class="cup-empty" role="status">${esc(CUP.boardError)} <button class="cup-link" data-action="cup-refresh-board">Повторить</button></p>`;
 if(!CUP.rows)return '<p class="cup-empty" role="status">Загружаем результаты…</p>';
 if(!CUP.rows.length)return '<div class="cup-empty"><b>Пока нет завершённых этапов.</b><p>Пройдите первый этап — результат появится здесь.</p></div>';
 return `<table class="cup-table"><caption class="sr-only">${CUP.board===-1?'Вся кампания':esc(CUP_LEVELS[CUP.board])}</caption><thead><tr><th scope="col">№</th><th scope="col">Аналитик</th><th scope="col">${CUP.board===-1?'Этапы':'Этап'}</th><th scope="col">Очки</th><th scope="col">Время</th></tr></thead><tbody>${CUP.rows.map(r=>`<tr class="${r.player_id===CUP.player?.id?'cup-you':''}"><td>${r.rank}</td><th scope="row">${esc(r.name)}${r.player_id===CUP.player?.id?'<small>вы</small>':''}</th><td>${CUP.board===-1?r.progress+'/14':CUP.board+1}</td><td>${r.score.toLocaleString('ru-RU')}</td><td>${cupTime(r.duration)}</td></tr>`).join('')}</tbody></table>`;
}
