function cupRenameHTML(){return `<section class="cup-panel cup-rename" role="dialog" aria-modal="true" aria-labelledby="cup-panel-title"><header class="cup-panel-head"><h3 id="cup-panel-title">Имя в рекордах</h3><button class="cup-close" data-action="cup-close" aria-label="Закрыть">×</button></header><form id="cup-rename-form"><label for="cup-new-name">Имя или позывной</label><input id="cup-new-name" name="name" autocomplete="nickname" enterkeyhint="done" minlength="2" maxlength="32" required value="${attr(CUP.renameDraft??CUP.player?.name??'')}"><small>Прогресс и очки сохранятся.</small><p id="cup-message" class="cup-message" role="status">${esc(CUP.error)}</p><button class="arcade-play" type="submit"${CUP.busy?' disabled':''}>Сохранить имя</button></form></section>`;}
