async function cupStartDefault(forceNew=false){
 if(CUP.busy)return;
 if(!CUP.player){if(ARCADE.engine?.status!=='menu')cupOriginalAction('arcade-menu');cupRefreshUI(true);document.getElementById('cup-name')?.focus({preventScroll:true});return;}
 CUP.busy=true;CUP.error='';cupRefreshUI(true);
 try{
  await cupRefresh();
  if(!CUP.player)throw Error('Введите имя, чтобы начать игру.');
  // Explicit "continue from cloud" resolves a stale tab without overwriting the server.
  if(CUP.conflict){CUP.queue=[];CUP.run=null;CUP.conflict=false;CUP.attached=false;localStorage.removeItem('cmpon.cup.outbox.v1');}
  cupEnqueue();await cupFlush();if(CUP.queue.length)throw Error('Сохранение ждёт связи. Нажмите ещё раз после подключения.');
  const r=!forceNew&&cupPlayableRun();
  if(r){const d=await cupAPI('run?id='+encodeURIComponent(r.id));if(d.run.status!=='active')throw Error('Попытка уже завершена. Обновите подключение.');await cupLaunch(d.run,true);}
  else{const d=await cupAPI('start',{autoTournament:true,mode:ARCADE.mode,gameVersion:CUP_GAME_VERSION});await cupLaunch(d.run);}
 }catch(e){CUP.error=e.message;}finally{CUP.busy=false;cupRefreshUI(true);}
}
async function cupAction(action){
 try{
  if(action==='cup-records'){cupOpenPanel();return;}
  if(action==='cup-close'){cupClosePanel();return;}
  if(action==='cup-rename'){cupOpenPanel('rename');return;}
  if(action==='cup-refresh-board'){CUP.rows=null;const el=document.getElementById('cup-board');if(el)el.innerHTML=cupBoardHTML();await cupRefreshBoard();return;}
  if(action==='cup-refresh'){await cupRefresh();return;}
  if(action==='cup-play'||action==='cup-new'){await cupStartDefault(action==='cup-new');return;}
  if(action==='cup-guest'){cupEnqueue();await cupFlush();if(CUP.queue.length)throw Error('Сохранение ещё не отправлено. Дождитесь подключения.');if(CUP.panel)cupClosePanel(false);CUP.attached=false;CUP.run=null;startArcade();return;}
 }catch(e){CUP.error=e.message;cupRefreshUI(true);}
}
const cupOriginalAction=arcadeAction;arcadeAction=function(action,value){
 if(action.startsWith('cup-')){void cupAction(action,value);return true;}
 if(CUP.panel&&action!=='arcade-expand'&&!action.startsWith('arcade-music'))return true;
 if(action==='arcade-start'&&location.protocol!=='file:'){void cupStartDefault(ARCADE.engine?.status!=='menu');return true;}
 if(['citadel-continue','finale-restore'].includes(action)&&(CUP.run||CUP.player)){void cupStartDefault();return true;}
 if(action==='arcade-menu'&&location.protocol!=='file:'){cupEnqueue();CUP.attached=false;void cupRefresh().catch(e=>{CUP.error=e.message;cupRefreshUI();});}
 if(CUP.attached&&action==='arcade-mode'){toast('Сложность зафиксирована для этой попытки.');return true;}
 return cupOriginalAction(action,value);
};
const cupOriginalSetView=setView;setView=function(view,scroll){
 const records=view==='tournament';if(records)view='arcade';
 if(view!=='arcade'&&CUP.panel)cupClosePanel(false);
 cupOriginalSetView(view,scroll);if(records)cupOpenPanel();
};
const cupOriginalRenderArcade=renderArcade;renderArcade=function(){
 return cupOriginalRenderArcade().replace('<button data-action="arcade-pause"', '<button class="cup-top-button" data-action="cup-records" aria-label="Рекорды" title="Рекорды"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 20V12H9V20M9 20V5H15V20M15 20V9H20V20M2 20H22"/></svg><span>Рекорды</span></button><button data-action="arcade-pause"');
};
function setupTournament(){
 if(STATE.view==='tournament'||['#arcade','#tournament'].includes(location.hash))STATE.view='arcade';
 if(location.hash==='#tournament')CUP.panel='records';
 addEventListener('hashchange',()=>{if(['#arcade','#tournament'].includes(location.hash))setView(location.hash==='#tournament'?'tournament':'arcade',true);});
 try{const v=JSON.parse(localStorage.getItem('cmpon.cup.session.v1')||'null');if(v?.token){CUP.token=v.token;CUP.player=v.player;}const k=localStorage.getItem(CUP_DEVICE_KEY);if(/^cpd_[a-f0-9]{64}$/.test(k||''))CUP.deviceKey=k;}catch{}
 for(const type of ['input','change','focusout'])document.addEventListener(type,ev=>cupRememberName(ev.target));
 document.addEventListener('submit',async ev=>{
  if(!['cup-entry-form','cup-rename-form'].includes(ev.target.id))return;ev.preventDefault();if(CUP.busy)return;
  const rename=ev.target.id==='cup-rename-form',name=String(new FormData(ev.target).get('name')||'');if(rename)CUP.renameDraft=name;else CUP.nameDraft=name;CUP.busy=true;CUP.error='';
  const buttons=[...ev.target.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);
  try{
   if(rename){const d=await cupAPI('profile',{name});CUP.player=d.player;cupPersist();cupClosePanel();}
   else{await cupEnsureProfile(name);CUP.busy=false;await cupStartDefault();}
  }catch(e){CUP.error=e.message;}finally{CUP.busy=false;buttons.forEach(b=>b.disabled=false);cupRefreshUI();}
 });
 document.addEventListener('change',ev=>{
  const id=ev.target.id;if(!['cup-select','cup-level','cup-mode'].includes(id))return;
  if(id==='cup-select')CUP.selected=ev.target.value;if(id==='cup-level')CUP.board=Number(ev.target.value);if(id==='cup-mode')CUP.mode=ev.target.value;
  CUP.rows=null;CUP.boardError='';cupRefreshUI(true);document.getElementById(id)?.focus();void cupRefreshBoard();
 });
 document.addEventListener('keydown',ev=>{
  if(!CUP.panel||STATE.view!=='arcade'||MOBILE.menu||MOBILE.command)return;ev.stopImmediatePropagation();
  if(ev.code==='Escape'){ev.preventDefault();cupClosePanel();return;}
  if(ev.code==='Tab'){const list=[...document.querySelectorAll('.cup-panel button:not([disabled]),.cup-panel select,.cup-panel input,.cup-panel a,.cup-panel [tabindex="0"]')];if(list.length){const i=list.indexOf(document.activeElement);if(ev.shiftKey&&(i<=0)){ev.preventDefault();list.at(-1).focus();}else if(!ev.shiftKey&&(i<0||i===list.length-1)){ev.preventDefault();list[0].focus();}}}
 },true);
 addEventListener('online',()=>void cupFlush());document.addEventListener('visibilitychange',()=>{if(document.hidden){ARCADE.engine?.pause();cupEnqueue();}});addEventListener('pagehide',()=>cupEnqueue());
 if(location.protocol!=='file:'){
  void cupRefresh().then(()=>{if(CUP.panel==='records')void cupRefreshBoard();}).catch(e=>{CUP.error=e.message;cupRefreshUI();});
  setInterval(()=>{if(CUP.run&&!CUP.conflict){cupEnqueue();void cupFlush();}},20000);
 }
}
async function cupRecoverOutbox(){
 if(!CUP.player)return;
 let p;try{p=JSON.parse(localStorage.getItem('cmpon.cup.outbox.v1')||'null');}catch{return;}
 if(p?.playerId!==CUP.player.id||!p.queue?.length)return;
 CUP.run=p.run;CUP.queue=p.queue;CUP.progress=p.progress;CUP.clock=p.clock;CUP.startClock=p.startClock;CUP.startScore=p.startScore;
 await cupFlush();if(!CUP.queue.length)CUP.run=null;
}

if(typeof globalThis.CITADEL_LAUNCH_INSTALL==='function')globalThis.CITADEL_LAUNCH_INSTALL();
if(!globalThis.ATLAS_TEST)initialize();
